    var Rm=rotM(pose.rot[0]),rp=[jr[0]+pose.pos[0],jr[1]+pose.pos[1],jr[2]+pose.pos[2]],dw=[J[iT][0]-rp[0],hy-rp[1],hz-rp[2]];
    var hl=[Rm[0]*dw[0]+Rm[1]*dw[1]+Rm[2]*dw[2],Rm[3]*dw[0]+Rm[4]*dw[1]+Rm[5]*dw[2],Rm[6]*dw[0]+Rm[7]*dw[1]+Rm[8]*dw[2]];
