GActor.prototype.play=function(c,fade){if(c===this.clip||!this.A.anims[c])return;this.from=this.clip;this.ft=this.t;this.clip=c;this.t=0;this.bl=0;this.fade=fade||0.25;};
GActor.prototype.scale=function(){return this.h/Math.max(0.01,this.A.hi[1]-this.A.lo[1]);};
GActor.prototype.update=function(dt){var A=this.A,rt=1;
  // 走路／跑步動畫速度配合實際移動速度，避免滑步
  if(this.speed>0.05){if(this.clip===this.walkClip)rt=this.speed/(this.natW||this.vWalk);else if(this.clip===this.runClip)rt=this.speed/(this.natR||this.vRun);rt=Math.max(0.55,Math.min(1.8,rt));}
  this.t+=dt*rt;if(this.from){this.ft+=dt;this.bl=Math.min(1,this.bl+dt/this.fade);if(this.bl>=1)this.from=null;}
  var an=A.anims[this.clip],d=an?an.dur:1,once=this.once&&this.clip===this.once;
  if(once&&this.t>=d){this.once=null;this.play(this.idleClip,0.3);}
  var ta=once?Math.min(this.t,d):this.t%Math.max(0.01,d),tb=this.from&&A.anims[this.from]?this.ft%Math.max(0.01,A.anims[this.from].dur):0;
  var s=this.scale();actBow(this,dt);var root=M4.mul(M4.trs([this.pos[0],-A.lo[1]*s+(this.y||0)+(this.yOff||0)+(this.yIK||0),this.pos[2]],this.yaw+this.fwd,0,[s,s,s]),rotX(this.bowA));
  this.P=gpose(A,this.clip,ta,this.from,tb,root,this.bl,this.fx);this.root=root;};
GActor.prototype.draw=function(u,depth){var P=this.P;if(!P||this.hidden)return;var A=this.A,I=M4.ident();
  if(!depth){gl.uniform1f(u.uUseTex,3);gl.uniform1f(u.uRough,0.62);gl.uniform1f(u.uMetal,0);var k=CFG.bright;gl.uniform3fv(u.uTint,[k,k,k]);}
  A.prims.forEach(function(p){var M=p.skinned?I:P.world[p.node];gl.uniform1f(u.uSkin,p.skinned?1:0);if(p.skinned)gl.uniformMatrix4fv(u.uB,false,P.jm);
    gl.uniformMatrix4fv(u.uModel,false,M);if(!depth)gl.uniformMatrix3fv(u.uNM,false,M4.normal(M));
    gl.bindVertexArray(depth?p.dvao:p.vao);gl.drawElements(gl.TRIANGLES,p.n,p.it,0);});};
// 躬身行禮：整個身體以腳為軸往前傾（bow 為目標角度，0＝站直）
function rotX(a){a=a||0;var c=Math.cos(a),n=Math.sin(a);return new Float32Array([1,0,0,0,0,c,n,0,0,-n,c,0,0,0,0,1]);}
function actBow(o,dt){var t=o.bow||0;o.bowA=(o.bowA||0)+(t-(o.bowA||0))*Math.min(1,dt*5);}
