var WAR=null;
function warAsset(){return WARM;}
function WActor(o){this.kind='war';this.name=o.name;this.pos=o.pos.slice();this.yaw=o.yaw||0;this.h=o.h||1.8;this.clip='idle';this.t=Math.random()*4;this.from=null;this.ft=0;this.bl=1;this.speed=0;this.vWalk=1.1;this.vRun=3;
  this.walkClip='walk';this.runClip='run';this.idleClip='idle';}
WActor.prototype.play=function(c,fade){if(c===this.clip)return;this.from=this.clip;this.ft=this.t;this.clip=c;this.t=0;this.bl=0;this.fade=fade||0.25;};
WActor.prototype.update=function(dt){var C=HeroAnim.CLIPS,LOOPW={idle:1,walk:1,run:1};this.t+=dt;if(this.from){this.ft+=dt;this.bl=Math.min(1,this.bl+dt/this.fade);if(this.bl>=1)this.from=null;}
  var f=C[this.clip];if(!LOOPW[this.clip]&&!f.loop&&f.dur&&this.t>=f.dur){this.play('idle',0.3);}
  function ev(c,tt){var g=C[c];return g(g.dur&&(LOOPW[c]||g.loop)?tt%g.dur:Math.min(tt,g.dur||tt));}
  var pose=ev(this.clip,this.t);if(this.from)pose=HeroAnim.mix(ev(this.from,this.ft),pose,this.bl*this.bl*(3-2*this.bl));if(this.lookP)this.lookP(pose,dt);
  var w=warAsset();HeroAnim.solve(w.skel,pose);var s=this.h/1.8;actBow(this,dt);
  this.model=M4.mul(M4.trs([this.pos[0],this.y||0,this.pos[2]],this.yaw,0,[s,s,s]),rotX(this.bowA));this.nm=M4.normal(this.model);this.bones=HeroAnim.skin(w.skel,pose,M4.mul);
  var hb=this.bones.subarray(10*16,10*16+16);this.mace=M4.mul(this.model,M4.mul(hb,mace.rest));this.maceNm=M4.normal(this.mace);};
WActor.prototype.draw=function(u,depth){var w=warAsset();if(!w||!this.bones)return;
  gl.uniform1f(u.uSkin,1);gl.uniformMatrix4fv(u.uB,false,this.bones);gl.uniformMatrix4fv(u.uModel,false,this.model);if(!depth)gl.uniformMatrix3fv(u.uNM,false,this.nm);
  gl.bindVertexArray(w.m.vao);
  if(depth)gl.drawElements(gl.TRIANGLES,w.m.n,gl.UNSIGNED_SHORT,0);
  else{gl.uniform1f(u.uUseTex,1);var k=CFG.bright*0.95;gl.uniform3fv(u.uTint,[k,k,k]);w.groups.forEach(function(g){gl.activeTexture(gl.TEXTURE3);gl.bindTexture(gl.TEXTURE_2D,g.tex);gl.uniform1f(u.uRough,g.mat.rough);gl.uniform1f(u.uMetal,g.mat.metal);gl.drawElements(gl.TRIANGLES,g.n,gl.UNSIGNED_SHORT,g.start*2);});}
  gl.uniform1f(u.uSkin,0);gl.uniformMatrix4fv(u.uModel,false,this.mace);if(!depth)gl.uniformMatrix3fv(u.uNM,false,this.maceNm);gl.bindVertexArray(mace.m.vao);
  if(!depth){gl.uniform1f(u.uUseTex,2);gl.activeTexture(gl.TEXTURE3);gl.bindTexture(gl.TEXTURE_2D,mace.tex);gl.activeTexture(gl.TEXTURE4);gl.bindTexture(gl.TEXTURE_2D,mace.rm);gl.uniform1i(u.uRM,4);gl.uniform1f(u.uRough,0.4);gl.uniform1f(u.uMetal,1);}
  gl.drawElements(gl.TRIANGLES,mace.m.n,gl.UNSIGNED_SHORT,0);};
// 共用：往目標點走（到了就停），回傳是否到達
function walkTo(a,tx,tz,dt,run,stopD){var dx=tx-a.pos[0],dz=tz-a.pos[2],d=Math.hypot(dx,dz);stopD=stopD||0.4;
  if(d<stopD){a.speed=0;a.vc=0;if(a.clip===a.walkClip||a.clip===a.runClip)a.play(a.idleClip,0.3);return true;}
  var ty=Math.atan2(dx,dz),dy=Math.atan2(Math.sin(ty-a.yaw),Math.cos(ty-a.yaw));a.yaw+=dy*Math.min(1,dt*5);
  var vt=(run?a.vRun:a.vWalk)*(a.spdK||1)*Math.max(0,Math.cos(dy))*(a._wp?1:Math.min(1,0.3+(d-stopD)/0.9));a.vc=(a.vc||0)+(vt-(a.vc||0))*Math.min(1,dt*3.2);var v=a.vc;a.speed=v;/* 起步加速、到點減速 */a.pos[0]+=Math.sin(a.yaw)*v*dt;a.pos[2]+=Math.cos(a.yaw)*v*dt;
  var want=run?a.runClip:a.walkClip;if(a.clip!==want&&!a.once)a.play(want,0.2);return false;}
function faceTo(a,tx,tz,dt){var ty=Math.atan2(tx-a.pos[0],tz-a.pos[2]),dy=Math.atan2(Math.sin(ty-a.yaw),Math.cos(ty-a.yaw));a.yaw+=dy*Math.min(1,dt*4);}

