  var pos=new Uint16Array(buf,o,n*3);o+=n*6;var uv=new Uint16Array(buf,o,n*2);o+=n*4;
  var nr=new Int8Array(buf,o,n*3);o+=n*3;var cb=new Int8Array(buf,o,n*3);o+=n*3;var jj=new Uint8Array(buf,o,n*4);o+=n*4;var ww=new Uint8Array(buf,o,n*4);o+=n*4;var xx=new Uint8Array(buf,o,n*2);
  var SEG=4,tv=[],ti=[];for(var i=0;i<=SEG;i++){tv.push(i/SEG,-1,i/SEG,1);if(i<SEG){var a=i*2;ti.push(a,a+1,a+2,a+1,a+3,a+2);}}
