    ['thighL','shinL','thighR','shinR'].forEach(function(n){m(n,v.legW,v.legL,v.legL);});['thighL','thighR'].forEach(function(n){m(n,1,(1+v.legW)/2,(1+v.legW)/2);});
    m('footL',v.footW,1,v.footL);m('footR',v.footW,1,v.footL);
