  if(joy){var dx=joy.x-joy.x0,dy=joy.y-joy.y0,l=Math.hypot(dx,dy),R=56;if(l>6){sx=dx/l;sy=dy/l;m=Math.min(1,l/R);}knobEl.style.transform='translate('+(sx*Math.min(l,R))+'px,'+(sy*Math.min(l,R))+'px)';}
