// ---------- 角色動作、血量、流血 ----------
var fur={len:0.005,den:1100,droop:0.35};
var LOOP={idle:1,hop:1,creep:1,chew:1,dig:1,sploot:1,flopLie:1};
var BTN={idle:'aIdle',hop:'aHop',creep:'aCreep',leap:'aLeap',groom:'aGroom',stand:'aStand',chew:'aChew',dig:'aDig',flop:'aFlop',sploot:'aSploot'};
var act={clip:'idle',t:0,from:null,fromT:0,blend:1,pick:'idle',fwd:0,freeze:false,speed:1};
function mark(c){Object.keys(BTN).forEach(function(k){$(BTN[k]).setAttribute('aria-pressed',String(k===c||(c==='flopLie'&&k==='flop')));});}
function commit(){if(act.fwd){hero.pos[0]+=Math.sin(hero.yaw)*act.fwd;hero.pos[2]+=Math.cos(hero.yaw)*act.fwd;act.fwd=0;}}
function go(c,fade){if(c===act.clip&&LOOP[c])return;commit();act.from=act.clip;act.fromT=act.t;act.clip=c;act.t=0;act.blend=0;act.fade=fade||0.3;}
