function nightK(){if(!CFG.dayNight)return 0;var h=G.hr%24;if(h<4)return 1;if(h<5)return 1-(h-4);if(h<18.5)return 0;if(h<20.5)return (h-18.5)/2;return 1;}
function duskK(){if(!CFG.dayNight)return 0;var h=G.hr%24;return Math.max(Math.max(0,1-Math.abs(h-18.3)/1.3),Math.max(0,1-Math.abs(h-5.4)/0.9)*0.6);}
function dayK(){if(!CFG.dayNight)return 1;var h=G.hr%24;for(var i=1;i<DAYK.length;i++)if(h<=DAYK[i][0]){var a=DAYK[i-1],b=DAYK[i],u=(h-a[0])/(b[0]-a[0]);return a[1]+(b[1]-a[1])*u;}return 1;}
function envApply(){var c=$('court-hud'),k=$('card');if(c)c.style.zoom=CFG.ui;if(k)k.style.zoom=CFG.ui;
  var f=$('cFollow');if(f)f.checked=!!CFG.follow;
  if(envApply.ph!==CFG.camPhi){envApply.ph=CFG.camPhi;cam.phi=CFG.camPhi;}
  if(envApply.dpr!==CFG.dpr){envApply.dpr=CFG.dpr;try{resize();}catch(e){}}}
function envUpdate(){var k=dayK();state.rot=CFG.rot;state.exp=CFG.exp*k;state.height=CFG.gh;state.mode=CFG.studio?'studio':'ground';
  var n=nightK(),du=duskK();
  var mn=CFG.moon?n:0;
  window.__ENVK={sun:CFG.sunK*Math.max(k*k,0.78*mn),amb:CFG.ambK*(0.55+0.45*k+0.45*n),night:n,dusk:du,
    tint:[1+n*(-0.28)+du*0.15,1+n*(-0.16)-du*0.08,1+n*0.18-du*0.25],sunT:[(1+du*0.35)*(1-mn)+0.62*mn,(1-du*0.15)*(1-mn)+0.76*mn,(1-du*0.45)*(1-mn)+1.18*mn]};}

