var SAMPLE=null;
function initAI(){var tries=0;function go(){tries++;try{if(window.claude&&window.claude.use){window.claude.use('sample').then(function(s){SAMPLE=s;aiBadge();},function(){aiBadge();});return;}}catch(e){}
  if(tries<6)setTimeout(go,800*tries);else aiBadge();}go();}
function aiOn(){return !!(SAMPLE&&CFG.ai);}
function aiBadge(){var b=$('aiState');if(b)b.textContent=aiOn()?'AI 出題：開':'AI 出題：未啟用（使用內建題庫）';}
function ask(prompt){if(!aiOn())return Promise.reject({code:'off'});return SAMPLE.json(prompt,{modelTier:CFG.tier});}
function chat(prompt){if(!aiOn())return Promise.reject({code:'off'});return SAMPLE(prompt,{modelTier:'quick',cache:false}).then(function(r){return r.text;});}
var TONE='語氣規則：第一句與最後一句用古代臣子對皇帝的恭敬語氣（例如：啟奏皇上、微臣遵旨、奴才惶恐、伏乞聖裁），稱呼玩家「皇上」「陛下」或「主子」。中間的核心內容一律用現代、自然、白話、好懂的台灣繁體中文，嚴禁文言文。以幫助玩家理解行政學為第一優先。';
function stat(){return '目前指標（0-100）：財政健全度'+G.ind[0]+'、民眾滿意度'+G.ind[1]+'、官僚效能感'+G.ind[2]+'、政治協調度'+G.ind[3]+'。';}
function qPrompt(sp,swan){var c=SYL[chIdx()],h=G.hist.slice(-3).map(function(x){return '「'+x.title+'」→ 選了：'+x.pick;}).join('；');
  return '你是一款行政學學習遊戲的出題官。玩家扮演唐朝皇帝，透過早朝的施政困境，以「深度理解、利弊權衡」的方式學習中華民國國家考試（高普考、特考、研究所）的行政學。\n'+
   '本題章節：第'+(chIdx()+1)+'章「'+c.t+'」；本日焦點：'+focus()+'。這是今天早朝第'+(G.qToday+1)+'題（共'+CFG.qPerDay+'題），請聚焦本日焦點中與前幾題不同的理論面向。\n'+
   '奏報者：'+PEOPLE[sp].n+'（'+PEOPLE[sp].role+'）。\n'+stat()+'\n'+(h?'近期決策：'+h+'\n':'')+(G.lastChain?'上一題的連鎖延伸事件：「'+G.lastChain+'」，請從這個事件延伸設計本題。\n':'')+
   (swan?'本題請設計成「黑天鵝事件」：突發、出乎意料、衝擊很大。\n':'')+(G.seenTitles.length?'已出過的題目（不要重複）：'+G.seenTitles.slice(-25).join('、')+'\n':'')+
   '要求：\n1. 場景在唐朝宮廷，但分析用現代行政學理論。困境要高度寫實、沒有完美解，四個選項都是殘酷的價值取捨（用某些指標換另一些指標），不可有明顯的最佳解。\n'+
   '2. 每個選項的 d 是四個指標的立即變動 [財政,民眾,效能,政治]，整數 -12 到 +12，每個選項至少一正一負。\n3. 每個選項都要有延遲後果（蝴蝶效應）dl：q 為幾題之後發生（2 到 6），d 為四指標變動，n 為後果描述。\n'+
   '4. 全部用台灣繁體中文、現代白話、清楚好懂，不要文言文。bg（當前背景）與 ev（困境事件）各 60 到 120 字，tp 為本題結合的 1 到 2 個行政學核心章節或概念。\n'+
   '5. exam：core 用 120 到 220 字講清楚理論與實務困境；masters 寫出相關學者與觀點；keys 給 4 到 6 個國考申論關鍵字；essay 給申論題作答架構。\n'+
   '6. 每個選項：t 選項內容（30 字內）、why 用 60 到 100 字說明這個選擇背後的理論與利弊、news 是一則諷刺或寫實的虛擬新聞頭條、next 是選這個選項後會引發的連鎖延伸事件（一句話）。\n'+
   '只輸出 JSON：{"title":"","bg":"","ev":"","tp":[""],"op":[{"t":"","d":[0,0,0,0],"dl":{"q":3,"d":[0,0,0,0],"n":""},"news":"","why":"","next":""}],"exam":{"core":"","masters":"","keys":[""],"essay":""}}，op 必須剛好 4 個。';}
function cleanQ(q,sp){if(!q||!q.op||q.op.length<4)throw new Error('格式不完整');
  function arr(a){a=(a||[]).slice(0,4);while(a.length<4)a.push(0);return a.map(function(x){x=Math.round(+x||0);return Math.max(-15,Math.min(15,x));});}
  q.op=q.op.slice(0,4).map(function(o){return {t:String(o.t||''),d:arr(o.d),dl:{q:Math.max(1,Math.min(8,Math.round((o.dl&&o.dl.q)||3))),d:arr(o.dl&&o.dl.d),n:String((o.dl&&o.dl.n)||'')},news:String(o.news||''),why:String(o.why||''),next:String(o.next||'')};});
  q.exam=q.exam||{};q.exam.keys=[].concat(q.exam.keys||[]);q.sp=sp;q.tp=[].concat(q.tp||[]);return q;}
// ---------- 開場與結尾語 ----------
var OPEN={m0:['啟奏皇上，','臣有本啟奏，','皇上，微臣斗膽進言，'],m1:['啟奏皇上，戶部有本。','皇上，臣有一事不得不奏，'],m2:['啟奏皇上，吏部有本。','臣啟陛下，'],pr:['兒臣叩見皇上，','皇上，兒臣有一事請教，'],eu:['奴才給皇上請安，','主子，奴才有事稟報，']};
var CLOSE={m0:['伏乞聖裁。','臣不勝惶恐，請皇上定奪。'],m1:['伏乞聖裁。','請皇上示下。'],m2:['伏乞聖裁。','臣惶恐待命。'],pr:['兒臣斗膽，請皇上定奪。','請皇上聖斷。'],eu:['奴才惶恐，請主子示下。','奴才多嘴了，主子恕罪。']};
var ACK={m0:['臣遵旨。','皇上聖明，微臣領旨。'],m1:['臣遵旨，戶部即刻辦理。','微臣領旨。'],m2:['臣遵旨。','吏部即刻照辦。'],pr:['兒臣遵旨。','皇上聖明，兒臣受教。'],eu:['奴才遵旨。','主子英明。']};
var BYE={m0:['臣告退。','皇上聖明，臣先行告退。'],m1:['臣告退。'],m2:['臣告退。'],pr:['兒臣告退。'],eu:['奴才告退。']};
function pick(a){return a[Math.floor(Math.random()*a.length)];}
// ---------- 介面工具 ----------
function esc(s){return String(s==null?'':s).replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c];});}
var UI={mode:'free'};
function openCard(html,cls){var c=$('card');c.className='card '+(cls||'');var mn=$('cardMin');if(mn)mn.hidden=G.court!=='on';$('cardBody').innerHTML=html;c.hidden=false;$('cardBody').scrollTop=0;UI.locked=true;}
function closeCard(){$('card').hidden=true;UI.locked=false;}
function toast(t,ms){var e=$('toast');e.textContent=t;e.hidden=false;clearTimeout(toast.h);toast.h=setTimeout(function(){e.hidden=true;},ms||3200);}
function dstr(d){return d.map(function(v,i){return v?'<span class="dv '+(v>0?'up':'dn')+'">'+INDI[i]+' '+IND[i]+' '+(v>0?'+':'')+v+'</span>':'';}).join('');}
function hud(){var p=phase();$('hDate').textContent='貞觀元年・第'+cnum(G.day+1)+'天・'+p[1]+'（'+p[2]+'）';
  $('hCh').textContent='第'+cnum(chIdx()+1)+'章 '+SYL[chIdx()].t+'・第'+cnum(dIdx()+1)+'天';
  var pg=$('hProg');if(pg){var st={wait:'早朝未開始',on:'早朝進行中',done:'早朝已畢',absent:'今日罷朝'}[G.court]||'',n=Math.min(G.qToday,CFG.qPerDay);
    pg.innerHTML='<span>今日進度：'+st+' '+n+'／'+CFG.qPerDay+' 奏・累計 '+G.qTotal+' 題</span><i style="width:'+(n/CFG.qPerDay*100)+'%"></i>';}
  for(var i=0;i<4;i++){var v=Math.max(0,Math.min(100,G.ind[i]));$('b'+i).style.width=v+'%';$('v'+i).textContent=Math.round(v);$('b'+i).className=v<20?'low':'';}}
function addInd(d,k){for(var i=0;i<4;i++)G.ind[i]=Math.max(0,Math.min(100,G.ind[i]+Math.round(d[i]*(k||1))));hud();}
// ---------- 早朝 ----------
var SPK=['m0','m1','m2','m0','m1','pr','m2','m0','m1','m2','pr','eu'];
function courtSeat(){// 百官入殿：直接就位，面向御座
  MIN.forEach(function(m,i){var c=LOC.court[i];m.pos=[c[0],0,c[1]];m.yaw=Math.atan2(LOC.throne[0]-c[0],LOC.throne[1]-c[1]);m.speed=0;m.play('idle',0.2);});
  PR.pos=[LOC.prAt[0],0,LOC.prAt[1]];PR.yaw=Math.atan2(LOC.throne[0]-LOC.prAt[0],LOC.throne[1]-LOC.prAt[1]);PR.once=null;PR.play('idle',0.2);
  EU.pos=[LOC.euCourt[0],0,LOC.euCourt[1]];EU.yaw=-1.2;EU.play('idle',0.2);
PL.pos=[LOC.throne[0],0,LOC.throne[1]];PL.y=DAIS;PL.yaw=0;PL.speed=0;PL.play('idle',0.2);
  if(CFG.fpCourt){window.__CT=null;fpOn();return;}
  window.__CT=[0,0,LOC.throne[1]+2.4];cam.target[0]=0;cam.target[2]=LOC.throne[1]+2.4;cam.theta=Math.PI+0.12;cam.phi=0.98;cam.r=7.4;cam.hold=2;}
function courtStart(){if(G.court!=='wait'||G.over)return;G.court='on';G.qToday=0;UI.mode='court';closeCard();courtSeat();hud();
  ceremony();}
// 出題：有內建題就用內建題，否則請 AI 出題；玩家閱讀上一題解析時就先在背景擬好下一題
var PRE=null;
function aiQ(sp,swan){return ask(qPrompt(sp,swan)).then(function(v){var q=cleanQ(v,sp);if(swan)q.swan=true;return q;});}
function prefetch(){if(!aiOn()||G.qToday>=CFG.qPerDay)return;var key=chIdx()+'-'+dIdx(),bank=BANK[key];if(bank&&bank[G.qToday])return;
  var sp=SPK[G.qTotal%SPK.length],swan=Math.random()*100<CFG.swan&&G.qToday>0,at=G.qTotal;PRE={at:at,p:aiQ(sp,swan)};PRE.p.catch(function(){});}
function getQ(cb){if(!BANKZ_OK&&BANKZ){loadBankZ(function(){BANKZ_OK=true;getQ(cb);});return;}var key=chIdx()+'-'+dIdx(),bank=BANK[key],sp=SPK[G.qTotal%SPK.length],swan=Math.random()*100<CFG.swan&&G.qToday>0;
  if(bank&&bank[G.qToday]&&!(swan&&aiOn())){cb(JSON.parse(JSON.stringify(bank[G.qToday])));return;}
  if(!aiOn()){var rv=reviewQ();if(rv){cb(rv);return;}cb(null);return;}
  openCard('<div class="wait"><div class="spin"></div><p>'+esc(PEOPLE[sp].n)+'正在擬奏摺…</p><p class="sub">AI 依「'+esc(focus())+'」出題，約需 10～60 秒</p></div>');
  var sent=G.qTotal,pr=PRE&&PRE.at===sent?PRE.p:aiQ(sp,swan);PRE=null;
  pr.then(function(q){if(G.qTotal!==sent)return;cb(q);},function(e){if(G.qTotal!==sent)return;
    if(e&&e.code==='rate_limited'){openCard('<p>今天問 AI 的次數太多了，請稍後再上朝。</p><div class="acts"><button class="b2" onclick="courtEnd(false)">退朝</button></div>');return;}
    if(e&&e.code==='not_granted'){CFG.ai=0;aiBadge();cb(null);return;}
    openCard('<p>奏摺擬得不太完整（AI 回覆格式有誤）。</p><div class="acts"><button class="b1" id="rt">請大臣重擬</button><button class="b2" onclick="courtEnd(false)">退朝</button></div>');$('rt').onclick=function(){courtAsk();};});}
// 離線複習：內建題用完且無 AI 時，從已出過的內建題中挑最久沒出的來複習
function reviewQ(){var all=[];for(var k in BANK)BANK[k].forEach(function(q){all.push(q);});if(!all.length)return null;
  var seen=G.seenTitles,best=null,bi=1e9;all.forEach(function(q){var i=seen.lastIndexOf(q.title);if(i<bi){bi=i;best=q;}});
  var q=JSON.parse(JSON.stringify(best));q.review=1;q.bg='（複習題）'+q.bg;return q;}
function courtNext(){if(G.over)return;
  // 延遲後果（蝴蝶效應）到期
  var due=G.pend.filter(function(p){return p.at<=G.qTotal;});G.pend=G.pend.filter(function(p){return p.at>G.qTotal;});
  if(due.length){aftDuePre(due);var h='<h3>⏳ 延遲後果浮現</h3>';due.forEach(function(p){addInd(p.d,CFG.delayK*CFG.mult);h+='<div class="delay"><b>源自「'+esc(p.src)+'」</b><p>'+esc(p.n)+'</p><div>'+dstr(p.d.map(function(x){return Math.round(x*CFG.delayK*CFG.mult);}))+'</div></div>';});
    if(checkEnd())return;openCard(h+'<div class="acts"><button class="b1" id="dGo">繼續早朝</button></div>');$('dGo').onclick=function(){courtAsk();};saveG();return;}
  courtAsk();}
function courtAsk(){if(G.qToday>=CFG.qPerDay){courtEnd(false);return;}
  getQ(function(q){if(!q){openCard('<h3>今天的奏摺還沒擬好</h3><p>內建題庫涵蓋全部十六章共六百四十題（每章另有二十題殿試選擇題），其餘章節由 AI 依課綱即時出題：請在 Claude 裡開啟這個遊戲，並在詢問時允許它使用 Claude。</p><div class="acts"><button class="b1" onclick="courtEnd(false)">退朝</button></div>');return;}
    q.sp=q.sp||SPK[G.qTotal%SPK.length];UI.q=q;showQ(q);});}
function showQ(q){UI.ans=null;var P=PEOPLE[q.sp],sp=NPC.filter(function(n){return n.id===q.sp;})[0];CER.spk=sp||null;if(sp)faceTo(sp,PL.pos[0],PL.pos[2],1);
  var h='<div class="who">'+esc(P.n)+'<span>第'+cnum(G.qToday+1)+'奏／共'+cnum(CFG.qPerDay)+'奏'+(q.swan?'・<b class="swan">黑天鵝</b>':'')+'</span></div>'+
   '<p class="court">'+esc(pick(OPEN[q.sp]))+'</p>'+
   '<h3>【當前回合與背景】</h3><p>'+esc(q.bg)+'</p><h3>【地獄級行政困境】'+esc(q.title||'')+'</h3><p>'+esc(q.ev)+'</p>'+
   (q.tp&&q.tp.length?'<div class="tags">'+q.tp.map(function(t){return '<span>'+esc(t)+'</span>';}).join('')+'</div>':'')+
   '<p class="court">'+esc(pick(CLOSE[q.sp]))+'</p><h3>【決策選項】</h3><div class="ops">'+q.op.map(function(o,i){return '<button class="op" data-i="'+i+'"><b>'+'ABCD'[i]+'</b>'+esc(o.t)+'</button>';}).join('')+'</div>';
  openCard(h,'q');[].forEach.call(document.querySelectorAll('#cardBody .op'),function(b){b.onclick=function(){choose(+b.dataset.i);};});}
function choose(i){var q=UI.q;if(!q||G.over||UI.ans===q)return;UI.ans=q;var o=q.op[i];if(!o)return;
  var d=o.d.map(function(x){return Math.round(x*CFG.mult);});addInd(d,1);
  G.pend.push({at:G.qTotal+1+o.dl.q,d:o.dl.d,n:o.dl.n,src:q.title});
  G.hist.push(Object.assign({title:q.title,pick:o.t,day:G.day,sp:q.sp},judgeDecision(q,i)));if(G.hist.length>60)G.hist.shift();G.seenTitles.push(q.title);if(G.seenTitles.length>80)G.seenTitles.shift();
  G.notes.push({ch:chIdx(),day:G.day,title:q.title,tp:q.tp,pick:o.t,why:o.why,exam:q.exam});if(G.notes.length>500)G.notes.shift();
  G.qToday++;G.qTotal++;G.lastChain=o.next;saveG();
  var ex=q.exam||{},h='<div class="who">'+esc(PEOPLE[q.sp].n)+'<span>皇上選擇 '+'ABCD'[i]+'</span></div><p class="court">'+esc(pick(ACK[q.sp]))+'</p>'+
   '<p class="picked">'+esc(o.t)+'</p><h3>【數值變動】</h3><div>'+(dstr(d)||'<span class="dv">指標沒有立即變動</span>')+'</div>'+
   '<h3>【虛擬新聞頭條】</h3><blockquote class="news">'+esc(o.news)+'</blockquote>'+
   '<h3>🎓【行政學考點解密】</h3><div class="exam"><p><b>這個抉擇：</b>'+esc(o.why)+'</p><p><b>理論核心：</b>'+esc(ex.core)+'</p>'+(ex.masters?'<p><b>大師觀點：</b>'+esc(ex.masters)+'</p>':'')+
   (ex.keys&&ex.keys.length?'<p><b>申論關鍵字：</b>'+ex.keys.map(function(k){return '<span class="key">'+esc(k)+'</span>';}).join('')+'</p>':'')+(ex.essay?'<p><b>答題架構：</b>'+esc(ex.essay)+'</p>':'')+'</div>'+
   (G.court==='on'?cerReact(q,d):'')+'<h3>【連鎖延伸事件】</h3><p>'+esc(o.next)+'</p><p class="sub">⏳ 這個決定還埋了一顆延遲後果，'+o.dl.q+' 奏之後會浮現。</p>'+
   '<p class="court">'+esc(pick(BYE[q.sp]))+'</p><div class="acts"><button class="b1" id="qGo">'+(G.qToday>=CFG.qPerDay?'退朝':'下一奏')+'</button></div>';
  if(checkEnd())return;openCard(h,'r');$('qGo').onclick=function(){courtNext();};prefetch();}
function courtEnd(absent){var R=R0();if(absent){fpOff();R.streak=0;}else{cerEnd();R.streak=R.lastCourt===G.day-1?R.streak+1:1;R.lastCourt=G.day;}G.court=absent?'absent':'done';UI.mode='free';window.__CT=null;cam.r=CFG.camR;cam.phi=CFG.camPhi;
  if(absent){addInd([0,-3,-4,-6],CFG.mult);openCard('<p class="court">奴才惶恐，主子今日未臨朝。</p><p>皇上缺席早朝，大臣們議而不決，政令延宕。罷朝的代價：官僚效能與政治協調下降。</p><div>'+dstr([0,-3,-4,-6])+'</div><p class="court">請主子保重龍體。</p><div class="acts"><button class="b1" onclick="closeCard()">知道了</button></div>');}
  else{G.hr=Math.max(G.hr,7);openCard('<p class="court">啟奏皇上，今日奏事已畢。</p><p>今日處理了 '+G.qToday+' 件政務。退朝前可參加殿試，用選擇題檢驗今天學到的考點；答錯的題目會收進錯題本。</p><p class="court">退朝——！</p><div class="acts"><button class="b1" onclick="dianShi()">參加殿試（'+CFG.dsN+' 題）</button><button class="b2" onclick="closeCard()">退朝</button><button class="b2" onclick="showNotes()">打開奏摺匣</button></div>');}
  saveG();if(!checkEnd())hud();}
// ---------- 結局 ----------
var DEATH=['財政破產：國庫空虛，連軍餉都發不出來','民心盡失：百姓揭竿而起，正當性崩潰','官僚癱瘓：政令出不了宮門，行政體系停擺','政治崩解：朝臣離心、藩鎮割據，皇權名存實亡'];
var DEATH_T=['預算失衡、財政紀律崩壞、Wildavsky 預算政治下的「花錢者」勝出、公共選擇學派說的預算極大化','正當性危機、回應性不足、新公共行政強調的社會公平被犧牲、民主行政失靈','官僚病理（目標錯置、繁文縟節）、Simon 的有限理性、執行落差、Lipsky 的基層官僚困境','政治支持流失、Rosenbloom 的政治途徑被忽略、利益團體與府際關係失衡'];
function checkEnd(){var k=G.ind.findIndex(function(v){return v<=0;});if(k<0)return false;G.over=true;saveG();ending(k);return true;}
function ending(k){var h='<h2 class="end">悲慘結局</h2><p class="court">皇上……大勢已去。</p><h3>'+INDI[k]+' '+DEATH[k]+'</h3><p>在位 '+(G.day+1)+' 天、處理 '+G.qTotal+' 件政務。</p>'+
   '<h3>🎓 行政學死因分析</h3><div class="exam" id="death"><p>'+esc(DEATH_T[k])+'。</p><p>回頭看最後幾個決定：</p><ul>'+G.hist.slice(-5).map(function(x){return '<li>「'+esc(x.title)+'」→ '+esc(x.pick)+'</li>';}).join('')+'</ul></div>'+
   '<div class="acts"><button class="b1" onclick="restart()">從本章重新登基</button><button class="b2" onclick="restart(true)">從第一章開始</button><button class="b2" onclick="showNotes()">奏摺匣</button></div>';
  openCard(h,'end');UI.mode='end';
  if(aiOn())ask('你是行政學老師。唐朝皇帝在一款行政學學習遊戲中失敗了，原因是「'+IND[k]+'」歸零（'+DEATH[k]+'）。最後的決策：'+G.hist.slice(-8).map(function(x){return '「'+x.title+'」選了「'+x.pick+'」';}).join('；')+'。請用台灣繁體中文、現代白話，寫一份「悲慘結局與行政學死因分析」：開頭一句、結尾一句用古代臣子對皇帝說話的語氣，中間用白話。分析哪些決策累積成這個結局、背後對應哪些行政學理論與國考申論關鍵字、下次可以怎麼權衡。只輸出 JSON：{"story":"結局描寫約80字","analysis":"死因分析約250字","keys":["關鍵字"]}').then(function(v){var e=$('death');if(!e)return;
    e.innerHTML='<p>'+esc(v.story)+'</p><p>'+esc(v.analysis)+'</p>'+([].concat(v.keys||[]).map(function(x){return '<span class="key">'+esc(x)+'</span>';}).join(''));},function(){});}
// 重新開始：預設從本章第一天重來（保留奏摺匣、殿試紀錄、成就），也可以選從第一章開始
function restart(all){window.__CT=null;fpOff();var ch=all?0:chIdx(),old=G;G=newGame();G.notes=old.notes;G.quiz=old.quiz;
  if(old.rpg){G.rpg=old.rpg;G.rpg.daily=null;G.rpg.dayStart=G.ind.slice();G.rpg.silent=0;G.rpg.refused={};G.rpg.streak=0;}
  G.day=ch*CFG.daysPerCh;LAST_PH=null;saveG();closeCard();PL.pos=[0,0,0.4];PL.yaw=Math.PI;hud();toast(ch?'重新登基——從第'+cnum(ch+1)+'章「'+SYL[ch].t+'」第一天開始':'新的一朝開始了',4500);}
// ---------- 奏摺匣（考點筆記） ----------
function showNotes(){var by={};G.notes.forEach(function(n){(by[n.ch]=by[n.ch]||[]).push(n);});
  var h='<h2>奏摺匣・考點筆記</h2><p class="sub">每一題的理論重點都收在這裡，照章節排列，方便考前複習。</p>'+studyMapHtml();
  var chs=Object.keys(by).sort(function(a,b){return a-b;});if(!chs.length)h+='<p>還沒有任何筆記，先上朝處理政務吧。</p>';
  chs.forEach(function(c){h+='<details open><summary>第'+cnum(+c+1)+'章 '+esc(SYL[c].t)+'（'+by[c].length+' 題）</summary>';
    by[c].forEach(function(n){var e=n.exam||{};h+='<div class="note"><b>'+esc(n.title)+'</b><p class="sub">你的選擇：'+esc(n.pick)+'</p><p>'+esc(e.core)+'</p>'+(e.keys?'<p>'+[].concat(e.keys).map(function(k){return '<span class="key">'+esc(k)+'</span>';}).join('')+'</p>':'')+(e.essay?'<p class="sub">答題架構：'+esc(e.essay)+'</p><button class="b2 sm" data-es="'+G.notes.indexOf(n)+'">✍ 練習申論</button>':'')+'</div>';});h+='</details>';});
  h+='<h3>全部章節</h3><ol class="syl">'+SYL.map(function(s,i){return '<li class="'+(i===chIdx()?'cur':'')+'">'+esc(s.t)+'<span>'+s.d.map(esc).join('｜')+'</span></li>';}).join('')+'</ol><div class="acts"><button class="b1" onclick="closeCard()">收起</button></div>';
  openCard(h,'notes');studyBind();}
// ---------- 與人對話 ----------
var TALK={who:null,log:[]};
function talkTo(n){R0()[n===hero?'rabDay':'talkDay']=G.day;TALK.who=n;TALK.log=[];UI.mode='talk';
  if(n===hero){openCard('<div class="who">白兔娘娘<span>後宮・不會說話</span></div><p>白兔用鼻子輕輕碰了碰你的手，耳朵轉向你。</p><div class="acts"><button class="b2" data-r="pet">摸摸頭</button><button class="b2" data-r="feed">餵一根胡蘿蔔</button><button class="b2" data-r="play">陪牠玩</button><button class="b1" data-r="x">離開</button></div>','talk');
    [].forEach.call(document.querySelectorAll('#cardBody [data-r]'),function(b){b.onclick=function(){var r=b.dataset.r;if(r==='x'){closeCard();UI.mode='free';return;}
      var m={pet:['flop','白兔舒服地瞇起眼睛，整隻翻倒側躺。'],feed:['chew','白兔捧著胡蘿蔔，下巴左右磨著，吃得好專心。'],play:['leap','白兔高高跳起，在空中扭了一下——這是兔子開心的「binky」。']}[r];
      rabPlay(m[0]);toast(m[1]);R0().rabN++;closeCard();UI.mode='free';};});return;}
  var P=PEOPLE[n.id],sug=n.id==='eu'?['今天有什麼安排？','宮裡最近有什麼消息？','教朕一個行政學觀念']:n.id==='pr'?['你最近在讀什麼新學問？','考考朕本章的重點','你覺得朝政哪裡該改革？']:['請卿解說本章重點','朕想複習剛才那一題','這個理論考試怎麼寫？'];
  var h='<div class="who">'+esc(P.n)+'<span>'+esc(P.role)+'</span></div><div id="tlog" class="tlog"><p class="court">'+esc(pick(OPEN[n.id]).replace(/[，,]$/,'。'))+'</p><p>'+(n.id==='eu'?'主子有什麼吩咐？想問行政學、問宮裡大小事，奴才都在。':'皇上想談什麼？不管是今天的政務，還是行政學的觀念，臣都可以說明。')+'</p></div>'+
   (aiOn()?'<div class="sug">'+sug.map(function(s){return '<button class="b2 sg">'+esc(s)+'</button>';}).join('')+'</div><form id="tf" class="tf"><input id="ti" autocomplete="off" placeholder="對'+esc(P.n)+'說…" maxlength="300"><button class="b1">說</button></form>':'<p class="sub">（在 Claude 裡開啟並允許 AI 後，可以和'+esc(P.n)+'自由對話、請教行政學。）</p>')+
   '<div class="acts"><button class="b2" id="tx">結束談話</button></div>';
  openCard(h,'talk');$('tx').onclick=function(){closeCard();UI.mode='free';};
  if(aiOn()){$('tf').onsubmit=function(e){e.preventDefault();var v=$('ti').value.trim();if(v)say(v);$('ti').value='';};[].forEach.call(document.querySelectorAll('#cardBody .sg'),function(b){b.onclick=function(){say(b.textContent);};});}}
function say(msg){R0().talkN++;var n=TALK.who,P=PEOPLE[n.id],lg=$('tlog');lg.insertAdjacentHTML('beforeend','<p class="me">皇上：'+esc(msg)+'</p><p class="sub" id="tw">'+esc(P.n)+'正在思考…</p>');lg.scrollIntoView({block:'end'});
  var last=G.hist.slice(-1)[0];
  var pr='你在一款唐朝宮廷背景的行政學學習遊戲中扮演「'+P.n+'」：'+P.role+'。自稱「'+P.self+'」。玩家是皇上。\n'+TONE+'\n回答 80 到 250 字，適時連結國考行政學理論與申論關鍵字。不要輸出 JSON。\n'+
    '目前：第'+(G.day+1)+'天 '+phase()[1]+'；本章「'+SYL[chIdx()].t+'」，今日焦點：'+focus()+'。'+stat()+(last?'剛才早朝最後一題：「'+last.title+'」，皇上選了「'+last.pick+'」。':'')+'\n'+
    (TALK.log.length?'先前對話：\n'+TALK.log.slice(-6).join('\n')+'\n':'')+'皇上說：'+msg;
  chat(pr).then(function(t){var w=$('tw');if(w)w.remove();TALK.log.push('皇上：'+msg,P.n+'：'+t);lg.insertAdjacentHTML('beforeend','<p>'+esc(t).replace(/\n/g,'<br>')+'</p>');lg.scrollIntoView({block:'end'});},
    function(e){var w=$('tw');if(w)w.textContent=e&&e.code==='rate_limited'?'今天問得太多了，稍後再談吧。':'（暫時無法回答，請再說一次。）';});}
// ---------- 白兔（後宮）的行為 ----------
var RAB={t:0,tg:null,wait:2,pl:null};
function inHall(x,z){return Math.abs(x)<4.4&&z>-6.7&&z<1.3;}
function rabPlay(c){RAB.wait=6;RAB.tg=null;setClip(c);}
function rabAI(dt){input.x=0;input.z=0;input.mag=0;act.speed=1;
  if(RAB.wait>0){RAB.wait-=dt;return;}
  var p=hero.pos,ph=phase()[1],dPl=Math.hypot(PL.pos[0]-p[0],PL.pos[2]-p[2]);
  if(!RAB.tg){var courtTime=G.court==='on'||(G.hr>=4&&G.hr<7),plHall=inHall(PL.pos[0],PL.pos[2]);
    // 後宮嬪妃不上朝：寅、卯時與早朝進行中，白兔都待在後宮；其他時候也不進金鑾殿
    if(RAB.sum||(ph==='戌時'&&dPl<12)||(!courtTime&&!plHall&&Math.random()<0.25&&dPl<9)){RAB.sum=false;var a=Math.random()*6.28;RAB.tg=[PL.pos[0]+Math.cos(a)*1.6,PL.pos[2]+Math.sin(a)*1.6];}
    else if(!courtTime&&G.court!=='wait'){RAB.carpet=!RAB.carpet&&Math.random()<0.7||(RAB.carpet&&Math.random()<0.5);
      if(RAB.carpet){RAB.tg=[(Math.random()-0.5)*1.5,-3.3+Math.random()*3.7];}else{var a2=Math.random()*6.28,r2=Math.sqrt(Math.random())*CFG.rabRange;RAB.tg=[Math.sin(a2)*r2,Math.cos(a2)*r2];}}
    else{var sp=courtTime?1.6:5;for(var k=0;k<8;k++){RAB.tg=[LOC.harem[0]+(Math.random()-0.5)*sp,LOC.harem[1]+(Math.random()-0.5)*sp*0.8];if(!inHall(RAB.tg[0],RAB.tg[1]))break;}}}
  window.__RABR=(G.court==='on'||G.court==='wait')?Math.max(9,Math.hypot(hero.pos[0],hero.pos[2])+0.05):CFG.rabRange+1;
  var dx=RAB.tg[0]-p[0],dz=RAB.tg[1]-p[2],d=Math.hypot(dx,dz);
  if(d<0.8){RAB.tg=null;if(RAB.carpet){RAB.wait=10+Math.random()*14;setClip(pick(['sploot','flopLie','groom','chew','sploot','stand']));return;}RAB.wait=3+Math.random()*7;if(Math.random()<0.45)setClip(pick(['groom','chew','dig','stand','sploot','idle','idle']));return;}
  var oneShot=!RabAnim.CLIPS[act.clip].loop;if(oneShot)return;
  input.x=dx/d;input.z=dz/d;input.mag=1;
  var sc=look.v.size*rabK,design=(input.mag>0.55?0.95:0.12)*sc;act.speed=Math.min(1,CFG.rabSpd/design);}
// ---------- NPC 行為 ----------
var EXTRA={who:null,t:0};
function npcUpdate(dt){var ph=phase()[1],court=G.court==='on';
  // 太監：上朝站在御座旁，其他時候跟在皇上身後
  if(EU===SUMMON.who){}else if(court)walkTo(EU,LOC.euCourt[0],LOC.euCourt[1],dt,false,0.3)&&faceTo(EU,PL.pos[0],PL.pos[2],dt);
  else if(typeof euFree==='function')euFree(dt);   // 平時侍立殿側，皇上偏離任務才來催（attend.js）
  else{var bx=PL.pos[0]-Math.sin(PL.yaw)*0.4-Math.cos(PL.yaw)*1.5,bz=PL.pos[2]-Math.cos(PL.yaw)*0.4+Math.sin(PL.yaw)*1.5,far=Math.hypot(bx-EU.pos[0],bz-EU.pos[2]);
    if(far>0.9)walkTo(EU,bx,bz,dt,far>4,0.5);else{EU.speed=0;if(EU.clip!=='idle')EU.play('idle');faceTo(EU,PL.pos[0],PL.pos[2],dt);}}
  // 大臣
  MIN.forEach(function(m,i){if(m===EXTRA.who||m===SUMMON.who||m===AFT.who||m===COUNCIL.who)return;var tg=court||ph==='卯時'?cerTarget(m,LOC.court[i]):aftSpot(i);
    if(walkTo(m,tg[0],tg[1],dt,court&&Math.hypot(tg[0]-m.pos[0],tg[1]-m.pos[2])>3,0.35)){if(court||ph==='卯時')faceTo(m,LOC.throne[0],LOC.throne[1],dt);else aftFace(m,dt);}});
  // 太子
  var pt=court||ph==='卯時'?cerTarget(PR,LOC.prAt):prSpot();
  if(PR!==SUMMON.who&&walkTo(PR,pt[0],pt[1],dt,true,0.4)){if(court)faceTo(PR,LOC.throne[0],LOC.throne[1],dt);else prTrain(dt);}
  // 大臣主動奏事（問政頻率）
  if(!court&&G.extraLeft>0&&!UI.locked&&!AFT.who&&R0().jianDay===G.day&&(ph==='巳時'||ph==='未時')&&Math.random()<dt/40){var m=pick(MIN);EXTRA.who=m;G.extraLeft--;toast(PEOPLE[m.id].n+'求見皇上');}
  if(EXTRA.who){var m2=EXTRA.who;if(walkTo(m2,PL.pos[0]+Math.sin(PL.yaw)*1.6,PL.pos[2]+Math.cos(PL.yaw)*1.6,dt,true,0.6)){faceTo(m2,PL.pos[0],PL.pos[2],dt);
      if(!UI.locked){EXTRA.who=null;extraAudience(m2);}}}}
function extraAudience(m){var P=PEOPLE[m.id];openCard('<div class="who">'+esc(P.n)+'<span>求見</span></div><p class="court">'+esc(pick(OPEN[m.id]).replace(/[，,]$/,'。'))+'</p><p>有一件急事，等不到明天早朝，想現在向皇上報告。</p><p class="court">不知皇上可否撥冗？</p><div class="acts"><button class="b1" id="xa">准奏</button><button class="b2" id="xb">改日再議</button></div>');
  $('xb').onclick=function(){closeCard();addInd([0,0,0,-1],1);toast(P.n+'：臣告退。');};$('xa').onclick=function(){extraAudience2(m);};}
function extraAudience2(m){UI.mode='court';var keep=G.qToday;getQ(function(q){if(!q){toast(PEOPLE[m.id].n+'：此事容後再奏。');UI.mode='free';return;}q.sp=m.id;UI.q=q;showQ(q);
  // 額外奏事不佔早朝題數
  var orig=choose;choose=function(i){orig(i);G.qToday=keep;choose=orig;var b=$('qGo');if(b){b.textContent='退下';b.onclick=function(){closeCard();UI.mode='free';};}};});}
// ---------- 作息 ----------
var LAST_PH=null;
function timeUpdate(dt){if(UI.locked||G.over||!CFG.timeOn)return;var rate=19/(Math.max(1,CFG.dayMin)*60)*((G.court==='done'||G.court==='absent')&&G.hr<21&&!window.__SLOW?CFG.afterK:1);G.hr+=dt*rate;var p=phase();
  if(p[1]!==LAST_PH){LAST_PH=p[1];onPhase(p);}
  if(G.court==='wait'&&G.hr>=7&&G.hr<7.2){courtEnd(true);}
  if(G.hr>=23)nextDay();hud();}
function onPhase(p){var t={寅時:'寅時到了，該起身梳洗了。',卯時:'卯時到了，百官已在金鑾殿候駕。走到金鑾殿，或按「上朝」。',辰時:'辰時：早膳已備好。',巳時:'巳時：可以去中書省找大臣議事，或四處走走。',午時:'午時：經筵開講，請到中書省書院。',未時:'未時：經筵講學。',申時:'申時：經筵已畢，可以出城逛大街市集。',酉時:'酉時：晚膳已備好，按「用晚膳」。',戌時:'戌時：後宮。白兔娘娘在等皇上。',亥時:'亥時：該就寢了，按「就寢」進入下一天。'}[p[1]];
  if(t)toast('🕰 '+t,4500);}
function nextDay(){R0().dayStart=G.ind.slice();G.day++;G.hr=4.2;G.qToday=0;G.court='wait';G.extraLeft=CFG.extraAsk;LAST_PH=null;
  var ch=chIdx();if(G.day%CFG.daysPerCh===0)toast('📜 進入第'+cnum(ch+1)+'章：'+SYL[ch].t,5000);
  if(G.day>0&&G.day%(SYL.length*CFG.daysPerCh)===0&&typeof gradCard==='function')setTimeout(function(){if(!G.over)gradCard();},2600);
  PL.pos=[0,0,0.4];PL.yaw=Math.PI;saveG();hud();}
// ---------- 每幀 ----------
var NEAR=null;
function gameUpdate(dt){if(!PL)return;timeUpdate(dt);
  // 皇上移動
  if(!UI.locked&&G.court!=='on'&&pin.mag>0.05&&!(typeof SIT!=='undefined'&&SIT.on)&&!window.__ATK&&!window.__ESC&&!window.__DASH){var stf=window.__STRAFE!=null,run=pin.mag>0.62&&!stf,ty=Math.atan2(pin.x,pin.z),dy=Math.atan2(Math.sin(ty-PL.yaw),Math.cos(ty-PL.yaw)),fast=(PL.vs||0)>PL.vWalk*1.25;if(!stf){if(fast&&Math.abs(dy)>2.2&&!window.__SKID){window.__SKID=0.16;PL.vs*=0.3;}   /* 跑步中反向推搖桿：先煞車再折返 */
      PL.yaw+=dy*Math.min(1,dt*(window.__SKID?16:fast?5.2:7.7));if(window.__SKID){window.__SKID=Math.max(0,window.__SKID-dt);}}var my=stf?ty:PL.yaw;   /* 拉弓時：身體對準目標，腳下照搖桿方向橫移 */
    var vt=stf?PL.vWalk*0.6*Math.min(1,pin.mag*1.4):pin.mag<0.5?PL.vWalk*Math.min(1,pin.mag*2.2):pin.mag<0.82?1.5:PL.vRun,   /* 輕推走、半推慢跑、推滿快跑 */vs=PL.vs||0;vs+=(vt-vs)*Math.min(1,dt*(vt>vs?3.9:8));PL.vs=vs;var v=vs;PL.speed=v;PL.pos[0]+=Math.sin(my)*v*dt;PL.pos[2]+=Math.cos(my)*v*dt;   /* 起步加速、換檔平順（不再瞬間全速） */if(typeof walkable==='function'){if(!walkable(PL.pos[0],PL.pos[2])){var ox=PL.pos[0]-Math.sin(my)*v*dt,oz=PL.pos[2]-Math.cos(my)*v*dt;   /* 走到邊界：沿邊滑動 */
      if(walkable(PL.pos[0],oz))PL.pos[2]=oz;else if(walkable(ox,PL.pos[2]))PL.pos[0]=ox;else{PL.pos[0]=ox;PL.pos[2]=oz;}if(!walkable(PL.pos[0],PL.pos[2])){var r0=Math.hypot(PL.pos[0],PL.pos[2]);if(r0>9.5){PL.pos[0]*=9.5/r0;PL.pos[2]*=9.5/r0;}}}}
    else{var r=Math.hypot(PL.pos[0],PL.pos[2]);if(r>9.5){PL.pos[0]*=9.5/r;PL.pos[2]*=9.5/r;}}
    if(PL.once!=='jump'&&PL.once!=='dash'&&PL.once!=='dashL'&&PL.once!=='stairs')PL.play(typeof plLoco==='function'?plLoco(v):(v>(PL.vWalk+PL.vRun)*0.5?'run':'walk'),0.22);}
  else if(!window.__ESC&&!window.__DASH){var vs2=(PL.vs||0)-dt*(PL.vs>PL.vWalk?9:6);   /* 放開搖桿：順勢滑步減速，不會瞬間定住 */
    if(vs2>0.15&&!UI.locked&&G.court!=='on'&&!window.__ATK){PL.vs=vs2;PL.speed=vs2;var nx=PL.pos[0]+Math.sin(PL.yaw)*vs2*dt,nz=PL.pos[2]+Math.cos(PL.yaw)*vs2*dt;if(typeof walkable!=='function'||walkable(nx,nz)){PL.pos[0]=nx;PL.pos[2]=nz;}if(PL.clip!==PL.walkClip&&isLoco(PL.clip)&&vs2<PL.vWalk*1.1)PL.play(PL.walkClip,0.25);}
    else{PL.vs=0;if(!window.__TURN){PL.speed=0;if(isLoco(PL.clip))PL.play('idle',0.3);}}}
  PL.y=(PL.y||0)+((onDais(PL.pos[0],PL.pos[2])?DAIS:(typeof terrH==='function'?terrH(PL.pos[0],PL.pos[2]):0))-(PL.y||0))*Math.min(1,dt*10);
  // 上朝時走到御座
  if(G.court==='wait'&&phase()[1]==='卯時'&&Math.hypot(PL.pos[0]-LOC.throne[0],PL.pos[2]-LOC.throne[1])<1.6&&!UI.locked)courtStart();
  envUpdate();npcUpdate(dt);ACT.forEach(function(a){a.update(dt);});
  // 誰在旁邊
  var best=null,bd=CFG.talkDist;[hero].concat(NPC).forEach(function(n){var p=n===hero?hero.pos:n.pos,d=Math.hypot(p[0]-PL.pos[0],p[2]-PL.pos[2]);if(d<bd){bd=d;best=n;}});NEAR=best;
  viewUpdate();rpgUpdate(dt);afterUpdate(dt);ctxBtn();labels();}
function ctxBtn(){var b=$('ctx'),ph=phase()[1];if(UI.locked||G.over){b.hidden=true;return;}b.hidden=false;
  if(G.court==='on'&&$('card').hidden){b.textContent='繼續早朝';b.onclick=function(){UI.mode='court';courtNext();};return;}
  if(G.court==='wait'&&ph==='卯時'){b.textContent='擺駕上朝';b.onclick=function(){courtStart();};return;}
  if(ph==='亥時'&&(!NEAR||NEAR===EU)){b.textContent='就寢';b.onclick=daySummary;return;}
  if(NEAR){b.textContent=NEAR===hero?'找白兔娘娘':'與'+(PEOPLE[NEAR.id].n.split(' ')[0])+'交談';b.onclick=function(){talkTo(NEAR);};return;}
  
  b.hidden=true;}
