var LBL=[];
function labels(){var VP=window.__VP;if(!VP)return;var box=$('lbls');
  var list=[[PL,'皇上',2.0]].concat(NPC.map(function(n){return [n,PEOPLE[n.id].n,(n.h||1.8)+0.25];})).concat([[hero,'白兔娘娘',CFG.hRab/100+0.2]]).concat(PLACES.map(function(p){return [{pos:[p[1][0],0,p[1][1]]},p[0],0.15,1];}));
  while(LBL.length<list.length){var e=document.createElement('div');e.className='lbl';box.appendChild(e);LBL.push(e);}
  list.forEach(function(it,i){var o=it[0],p=o===hero?(hero.wp||hero.pos):o.pos,x=p[0],y=it[2],z=p[2],e=LBL[i];
    var cx=VP[0]*x+VP[4]*y+VP[8]*z+VP[12],cy=VP[1]*x+VP[5]*y+VP[9]*z+VP[13],cw=VP[3]*x+VP[7]*y+VP[11]*z+VP[15];
    var far=Math.hypot(x-PL.pos[0],z-PL.pos[2])>(it[3]?CFG.lblDist*1.6:CFG.lblDist)&&o!==PL;
    if(far||(o===PL&&G.court==='on')||cw<0.1||Math.abs(cx/cw)>1.1||Math.abs(cy/cw)>1.1){e.style.display='none';return;}
    e.style.display='block';e.style.left=((cx/cw*0.5+0.5)*innerWidth)+'px';e.style.top=((0.5-cy/cw*0.5)*innerHeight)+'px';e.textContent=it[1];e.className='lbl'+(it[3]?' place':'')+(o===NEAR?' near':'');});}
