function schKey(n){return n.replace(/^[A-Z]{1,2}\.\s*/,'').replace(/（.*）/,'').trim();}
function schRel(a,b){a=schKey(a);b=schKey(b);return a.indexOf(b)>=0||b.indexOf(a)>=0;}
function schQ(k){var s=SCH[k],same=SCH.filter(function(x){return !schRel(x[0],s[0])&&x[1]!==s[1];}),pool=same.filter(function(x){return Math.abs(x[2]-s[2])<=1;});
  if(pool.length<3)pool=same;pool=pool.slice().sort(function(){return Math.random()-0.5;});
  var rev=Math.random()<0.4,opts=[],seen={};opts.push(rev?s[1]:s[0]);seen[opts[0]]=1;
  for(var i=0;i<pool.length&&opts.length<4;i++){var v=rev?pool[i][1]:pool[i][0];if(!seen[v]){seen[v]=1;opts.push(v);}}
  var ord=[0,1,2,3].sort(function(){return Math.random()-0.5;}),o=ord.map(function(j){return opts[j];});
  return {c:s[2],i:-1,s:k,q:rev?'「'+s[0]+'」提出或主張的是：':'「'+s[1]+'」是哪一位（些）學者提出的？',o:o,a:ord.indexOf(0),why:s[0]+'：'+s[1]+'（第'+cnum(s[2]+1)+'章 '+SYL[s[2]].t+'）。'};}
function quizQ(c,i){var x=QUIZ[c][i];return {c:c,i:i,q:x[0],o:x[1],a:x[2],why:x[3]};}
function acHas(c){return !!(BANK[c+'-0']||QUIZ[c]);}
