var BODY_R=0.3,OBST=null,RAB_R=0.27,
  RAB_OBST=[{t:'b',x:0,z:-4.92,w:1.75,d:1.3}];   // 丹陛（含台階）：兔子跳不上去，視為障礙
function obstBuild(){var o=[],c=function(x,z,r){o.push({t:'c',x:x,z:z,r:r});},b=function(x,z,w,d){o.push({t:'b',x:x,z:z,w:w/2,d:d/2});};
  [-3.9,3.9].forEach(function(x){[-5.0,-2.2,0.6].forEach(function(z){c(x,z,0.36);});});   // 朱紅大柱
  [-2.2,2.2].forEach(function(x){c(x,-3.9,0.26);});                                        // 香爐
  [LOC.office,LOC.east,LOC.harem,LOC.bed].forEach(function(p){c(p[0]+0.9,p[1]-0.9,0.14);});  // 燈柱
  b(LOC.office[0],LOC.office[1]-0.2,1.2,0.6);                                              // 中書省書案
  if(!CFG.dragon)b(0,-6.4,4.3,0.16);else{b(0,-8.2,4.0,4.0);b(0,-15.5,3.4,8.0);}   // 屏風；有黑龍時改成龍身（兩翼在頭頂上方，可從下方走過）
  c(FIRE_POS[0],FIRE_POS[2],0.72);[-2.75,2.75].forEach(function(x){c(x,-4.6,0.36);});   // 營火、天子劍座                                                                      // 御座後屏風
  c(LOC.east[0]-0.6,LOC.east[1]-1.0,0.08);c(LOC.east[0]+0.6,LOC.east[1]-1.0,0.08);           // 兵器架
  c(LOC.east[0]+1.2,LOC.east[1]+0.4,0.16);                                                 // 練武木樁
  return o;}
function pushOut(a,o){var p=a.pos,r=BODY_R;
  if(o.t==='c'){var dx=p[0]-o.x,dz=p[2]-o.z,d=Math.hypot(dx,dz),m=o.r+r;if(d<m){if(d<1e-4){dx=1;dz=0;d=1;}p[0]=o.x+dx/d*m;p[2]=o.z+dz/d*m;}}
  else{var cx=Math.max(o.x-o.w,Math.min(o.x+o.w,p[0])),cz=Math.max(o.z-o.d,Math.min(o.z+o.d,p[2])),ex=p[0]-cx,ez=p[2]-cz,e=Math.hypot(ex,ez);
    if(e<r){if(e<1e-4){var l=p[0]-(o.x-o.w),rr=(o.x+o.w)-p[0],t=p[2]-(o.z-o.d),bt=(o.z+o.d)-p[2],mn=Math.min(l,rr,t,bt);
        if(mn===l)p[0]=o.x-o.w-r;else if(mn===rr)p[0]=o.x+o.w+r;else if(mn===t)p[2]=o.z-o.d-r;else p[2]=o.z+o.d+r;}
      else{p[0]=cx+ex/e*r;p[2]=cz+ez/e*r;}}}}
function bodies(){var L=[PL,EU,PR].concat(MIN);return L.filter(function(a){return a&&a.pos&&!a.hidden&&!(a===PR&&PR.flight);});}
function collide(){if(!CFG.collide||G.over)return;if(UI.mode==='court'&&G.court==='on')return; // 早朝就位時不推動
  if(!OBST)OBST=obstBuild();var B=bodies(),i,j;
  for(i=0;i<B.length;i++)for(j=i+1;j<B.length;j++){var a=B[i],b=B[j],dx=b.pos[0]-a.pos[0],dz=b.pos[2]-a.pos[2],d=Math.hypot(dx,dz),m=BODY_R*2;
    if(d<m){if(d<1e-4){dx=1;dz=0;d=1;}var k=(m-d)/2,ux=dx/d,uz=dz/d,wa=a===EU?1:b===EU?0:a===PL?0.35:0.5,wb=b===EU?1:a===EU?0:b===PL?0.35:0.5;   // 太監一律讓開   // 皇上比較「重」，主要由 NPC 讓開
      a.pos[0]-=ux*k*2*wa;a.pos[2]-=uz*k*2*wa;b.pos[0]+=ux*k*2*wb;b.pos[2]+=uz*k*2*wb;}}
  B.forEach(function(a){if(a.y>DAIS*0.5&&onDais(a.pos[0],a.pos[2]))return;OBST.forEach(function(o){pushOut(a,o);});});
  if(typeof hero!=='undefined'&&hero&&hero.pos){var rb={pos:hero.pos};B.forEach(function(a){var dx=hero.pos[0]-a.pos[0],dz=hero.pos[2]-a.pos[2],d=Math.hypot(dx,dz),m=(a===PL&&typeof RAB!=='undefined'&&RAB.fav)?0.36:BODY_R+RAB_R;
    if(d<m){if(d<1e-4){dx=1;dz=0;d=1;}hero.pos[0]=a.pos[0]+dx/d*m;hero.pos[2]=a.pos[2]+dz/d*m;}});var r0=BODY_R;BODY_R=RAB_R;OBST.concat(RAB_OBST).forEach(function(o){pushOut(rb,o);});
    if(typeof RAB!=='undefined'&&RAB.tg){if(Math.abs(RAB.tg[0])<2.2&&RAB.tg[1]<-3.4&&RAB.tg[1]>-6.3)RAB.tg[1]=-3.4-Math.random()*0.8;   // 想去丹陛上就改到台階前
      var tg={pos:[RAB.tg[0],0,RAB.tg[1]]};BODY_R=RAB_R+0.15;OBST.concat(RAB_OBST).forEach(function(o){pushOut(tg,o);});RAB.tg[0]=tg.pos[0];RAB.tg[1]=tg.pos[2];}BODY_R=r0;}}
// ---------------- 名牌防重疊 ----------------
function lblDeclutter(){var L=[].slice.call(document.querySelectorAll('#lbls .lbl')).filter(function(e){return e.style.display!=='none'&&e.offsetParent!==null;});
  var R=L.map(function(e){return e.getBoundingClientRect();}),hide=[];
  for(var i=0;i<L.length;i++){if(L[i].classList.contains('place'))continue;for(var j=0;j<L.length;j++){if(i===j||hide[i])continue;var a=R[i],b=R[j];
    if(a.left<b.right-4&&b.left<a.right-4&&a.top<b.bottom-2&&b.top<a.bottom-2){if(a.top<b.top||(a.top===b.top&&i>j))hide[i]=1;}}}
  L.forEach(function(e,i){e.style.opacity=hide[i]?'0.18':'';});}
