  var _c=ctxBtn;ctxBtn=function(){_c.apply(this,arguments);if(G.court==='on'&&$('card').hidden&&!UI.locked&&!G.over){var b=$('ctx');b.hidden=false;b.textContent='繼續早朝';b.onclick=courtResume;}};
  var _q=quest;quest=function(){if(G.court==='on'&&$('card').hidden&&!G.over)return {t:'早朝暫停中：百官在金鑾殿候旨，按「繼續早朝」回朝',tg:LOC.throne};return _q.apply(this,arguments);};
