var YIELD={o:null,tg:null,until:0,bowed:false,last:{},sayT:0};
function yieldWho(o){return o===PL?'主子':o===PR?'殿下':(typeof hero!=='undefined'&&o===hero)?'白兔娘娘':'大人';}
function yieldScan(dt){if(window.__EUJOB||!CFG.collide||G.over||(UI.mode==='court'&&G.court==='on')||(typeof SUMMON!=='undefined'&&SUMMON.who===EU)){YIELD.o=null;return;}
  var now=performance.now(),L=[PL,PR].concat(MIN);if(typeof hero!=='undefined'&&hero&&hero.pos)L.push(hero);
  L.forEach(function(o){if(!o||!o.pos||o.hidden)return;var k=L.indexOf(o),lp=YIELD.last[k]||[o.pos[0],o.pos[2]],vx=(o.pos[0]-lp[0])/Math.max(dt,1e-3),vz=(o.pos[2]-lp[1])/Math.max(dt,1e-3);YIELD.last[k]=[o.pos[0],o.pos[2]];
    if(YIELD.o&&YIELD.until>now)return;if(o===PR&&PR.flight)return;
    var rx=EU.pos[0]-o.pos[0],rz=EU.pos[2]-o.pos[2],d=Math.hypot(rx,rz),sp=Math.hypot(vx,vz);if(d>2.2||d<1e-3)return;
    var ux=sp>1e-3?vx/sp:0,uz=sp>1e-3?vz/sp:0,app=sp>0.25&&(ux*rx+uz*rz)/d>0.35;if(!app&&d>0.75)return;
    var tg;if(app){var along=ux*rx+uz*rz,px=rx-ux*along,pz=rz-uz*along,pl=Math.hypot(px,pz);if(pl<0.05){px=-uz;pz=ux;pl=1;}tg=[o.pos[0]+ux*Math.max(along,0.6)+px/pl*1.35,o.pos[2]+uz*Math.max(along,0.6)+pz/pl*1.35];}
    else tg=[o.pos[0]+rx/d*1.4,o.pos[2]+rz/d*1.4];
    if(typeof navLOS==='function'&&!navLOS('h',EU.pos[0],EU.pos[2],tg[0],tg[1])){tg=[EU.pos[0]+rx/d*1.2,EU.pos[2]+rz/d*1.2];if(!navLOS('h',EU.pos[0],EU.pos[2],tg[0],tg[1]))return;}   /* 讓路的落點不能在柱子、劍座裡 */
    YIELD.o=o;YIELD.tg=tg;YIELD.until=now+2600;YIELD.bowed=false;
    if(now>YIELD.sayT&&typeof soulSay==='function'&&o!==PL||(o===PL&&now>YIELD.sayT&&Math.random()<0.3)){YIELD.sayT=now+18000;if(typeof soulSay==='function')soulSay(EU,yieldWho(o)+'請。',1800);}});}
