// ==========================================================================
// 紅毯前的營火（皇上提供的 camp_fire 模型＋火焰粒子＋暖色點光源，會閃爍、照亮周圍的人、地面與草）
// 御階兩側的天子劍（原創唐式儀刀，環首、金鐔、朱柄，劍尖插入石座）
// ==========================================================================
var FIRE_POS=[0,0,5.6];   // 皇上指定的位置：紅毯前方御道上
function Campfire(){var g=adecode(ASSET.campfire),S=1.25;this.m=mesh(g);this.tex=null;var self=this;atex(ASSET.campfire_tex,function(t){self.tex=t;});
  this.M=M4.trs(FIRE_POS,0.4,0,[S,S,S]);this.NM=M4.normal(this.M);}
Campfire.prototype.update=function(){};
Campfire.prototype.draw=function(u,depth){if(!CFG.fire||!this.tex)return;gl.uniform1f(u.uSkin,0);gl.uniformMatrix4fv(u.uModel,false,this.M);
  if(!depth){gl.uniformMatrix3fv(u.uNM,false,this.NM);gl.uniform1f(u.uUseTex,1);gl.activeTexture(gl.TEXTURE3);gl.bindTexture(gl.TEXTURE_2D,this.tex);gl.uniform3fv(u.uTint,[1.7,1.2,0.9]);gl.uniform1f(u.uRough,0.9);gl.uniform1f(u.uMetal,0);}
  gl.bindVertexArray(this.m.vao);gl.drawElements(gl.TRIANGLES,this.m.n,gl.UNSIGNED_SHORT,0);if(!depth)gl.uniform1f(u.uUseTex,0);};
// ---------- 火焰粒子（加色混合、面向鏡頭；用附件的 5×5 火焰序列圖） ----------
var VS_FX=`#version 300 es
in vec2 aPos;uniform mat4 uVP;uniform vec3 uO,uR,uU;uniform float uT,uKind,uNt;out vec2 vUV;out float vA,vF;
float h1(float n){return fract(sin(n*91.7)*43758.5453);}
void main(){float id=float(gl_InstanceID),r1=h1(id),r2=h1(id+7.1),r3=h1(id+13.7);
  float life=uKind<.5?mix(.7,1.2,r1):mix(1.6,2.6,r1),ph=fract(uT/life+r2);
  vec3 c=uO;float sz;
  if(uKind<.5){float a=r3*6.2832,rr=(.05+.22*r1)*(1.-ph*.7);c+=vec3(cos(a)*rr,.12+ph*(.7+.45*r2),sin(a)*rr);sz=mix(.3,.07,ph)*mix(.75,1.25,r3);vA=sin(ph*3.1416)*(1.-ph*.4)*.32;}
  else if(uKind>1.5){c+=vec3(0.,.55,0.);sz=uKind>2.5?.75:2.3;vA=1.;vF=0.;}   // 光暈：火堆本身是發光體
  else{float a=r3*6.2832,rr=.1+.5*ph*r1;c+=vec3(cos(a+uT*.7)*rr,.3+ph*2.3,sin(a+uT*.7)*rr);sz=.035;vA=(1.-ph)*.9*(.15+.85*uNt);}
  vF=floor(ph*24.);vec3 p=c+(uR*aPos.x+uU*aPos.y)*sz;vUV=aPos*.5+.5;gl_Position=uVP*vec4(p,1.);}`;
var FS_FX=`#version 300 es
precision highp float;in vec2 vUV;in float vA,vF;uniform sampler2D uS;uniform float uKind,uGl;out vec4 o;
void main(){vec3 col;float a;
  if(uKind<.5){vec2 cell=vec2(mod(vF,5.),floor(vF/5.));vec4 t=texture(uS,(cell+.08+vec2(vUV.x,1.-vUV.y)*.84)/5.);float h=vUV.y;
    col=t.rgb*mix(vec3(1.5,.55,.15),vec3(1.3,.9,.45),1.-h);col=mix(col,vec3(.35,.5,1.3)*t.a,(1.-smoothstep(0.,3.5,vF))*.4*(1.-h));a=t.a*vA*smoothstep(.0,.25,1.-length(vUV-.5)*1.6);}
  else if(uKind>1.5){float d=length(vUV-.5)*2.;float k=uKind>2.5?pow(max(0.,1.-d),1.6):pow(max(0.,1.-d),2.6);a=k*uGl;col=(uKind>2.5?vec3(1.,.62,.25):vec3(1.,.5,.16))*1.4;}
  else{float d=length(vUV-.5)*2.;a=max(0.,1.-d)*vA;col=vec3(1.,.6,.2)*2.;}
  o=vec4(col*a,a);}`;
var FXF={p:null,vao:null,tex:null,t0:performance.now()};
function fxDraw(vp,view){if(!CFG.fire||state.mode==='pano')return;if(!FXF.p){try{FXF.p=prog(VS_FX,FS_FX);}catch(e){CFG.fire=0;console.warn(e);return;}
    FXF.vao=gl.createVertexArray();gl.bindVertexArray(FXF.vao);var b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);gl.vertexAttribPointer(0,2,gl.FLOAT,false,0,0);gl.bindVertexArray(null);atex(ASSET.fire_sprite,function(t){FXF.tex=t;});}
  if(!FXF.tex)return;var u=FXF.p.u;gl.useProgram(FXF.p.p);gl.uniformMatrix4fv(u.uVP,false,vp);gl.uniform3fv(u.uR,[view[0],view[4],view[8]]);gl.uniform3fv(u.uU,[view[1],view[5],view[9]]);
  gl.uniform3fv(u.uO,[FIRE_POS[0],FIRE_POS[1],FIRE_POS[2]]);gl.uniform1f(u.uT,(performance.now()-FXF.t0)/1000);gl.uniform1f(u.uNt,(window.__ENVK&&window.__ENVK.night)||0);gl.activeTexture(gl.TEXTURE15);gl.bindTexture(gl.TEXTURE_2D,FXF.tex);gl.uniform1i(u.uS,15);
  gl.enable(gl.BLEND);gl.blendFunc(gl.ONE,gl.ONE);gl.depthMask(false);gl.bindVertexArray(FXF.vao);
  gl.uniform1f(u.uKind,0);gl.drawArraysInstanced(gl.TRIANGLE_STRIP,0,4,100);   /* v76：火焰 100 束 */
  gl.uniform1f(u.uKind,1);gl.drawArraysInstanced(gl.TRIANGLE_STRIP,0,4,64);
  var tt=performance.now()/1000,fl=0.85+0.1*Math.sin(tt*8.3)+0.05*Math.sin(tt*21.1),nt=(window.__ENVK&&window.__ENVK.night)||0;
  gl.uniform1f(u.uKind,2);gl.uniform1f(u.uGl,(0.27+0.32*nt)*fl);gl.drawArraysInstanced(gl.TRIANGLE_STRIP,0,4,1);   // 大光暈
  gl.uniform1f(u.uKind,3);gl.uniform1f(u.uGl,(0.47+0.26*nt)*fl);gl.drawArraysInstanced(gl.TRIANGLE_STRIP,0,4,1);    // 核心亮光
  gl.bindVertexArray(null);gl.depthMask(true);gl.disable(gl.BLEND);}
// 火光：暖橘色、隨機閃爍，夜裡更明顯
function fireLight(){if(!CFG.fire){window.__FIREC=null;return;}var t=performance.now()/1000,f=0.82+0.1*Math.sin(t*9.1)+0.06*Math.sin(t*23.7+1.3)+0.04*Math.sin(t*3.3),n=(window.__ENVK&&window.__ENVK.night)||0,I=(2.2+2.9*n)*f*(CFG.fireK||1);   // 白天也明顯發光，夜裡是主要光源
  window.__FIREP=[FIRE_POS[0]+Math.sin(t*5.3)*0.03,0.55,FIRE_POS[2]+Math.cos(t*4.1)*0.03];window.__FIREC=[I*1.0,I*0.52,I*0.2];}
// ---------- 天子劍（原創） ----------
function swordGeo(){var P=[],I=[],add=function(g,M){var o=P.length/3;for(var k=0;k<g.p.length;k+=3){var v=M(g.p[k],g.p[k+1],g.p[k+2]);P.push(v[0],v[1],v[2]);}g.i.forEach(function(x){I.push(x+o);});};
  return {P:P,I:I,add:add};}
function bladeMesh(L,W,T){var p=[],idx=[],R=40;   // 劍身：沿長度 R 段，每段 6 點的斷面（刀背厚、刃口薄、中間有脊）
  for(var j=0;j<=R;j++){var s=j/R,w=W*(1-0.12*s),tip=Math.max(0,(s-0.9)/0.1),back=-w*0.5,edge=w*0.5-w*tip*0.95,bk=back+w*0.7*tip*tip,y=-s*L;
    var tt=T*(1-0.6*tip);[[bk,tt*0.5],[bk+w*0.35,tt*0.45],[edge,0],[bk+w*0.35,-tt*0.45],[bk,-tt*0.5],[bk-0.003,0]].forEach(function(q){p.push(q[0],y,q[1]);});}
  for(j=0;j<R;j++)for(var i=0;i<6;i++){var a=j*6+i,b=j*6+(i+1)%6,c=a+6,d=b+6;idx.push(a,c,b,b,c,d);}
  var tipI=p.length/3;p.push(-W*0.5+W*0.7,-L*1.02,0);for(i=0;i<6;i++)idx.push(R*6+i,tipI,R*6+(i+1)%6);
  var P=new Float32Array(p),Id=new Uint16Array(idx);return {pos:P,nor:computeNormals(P,Id),idx:Id};}
function Swords(){var steel=lin(0xdfe4ea),gold=lin(0xd6a63c),red=lin(0x7a1210),stone=lin(0xb7ae9e),dark=lin(0x2a1a10);this.parts=[];var self=this;
  var S=1.0,L=2.05,W=0.17;
  var bl=mesh(bladeMesh(L,W,0.045)),cyl=mesh(geoCyl(1,1,1,20)),sph=mesh(geoSphere(1,16,10)),box=mesh(geoBox(1,1,1));
  var tor=(function(){var p=[],n=[],idx=[],R=1,r=0.24,A=28,B=10;for(var j=0;j<=A;j++)for(var i=0;i<=B;i++){var a=j/A*Math.PI*2,b=i/B*Math.PI*2,cx=Math.cos(a),cy=Math.sin(a);
      p.push((R+r*Math.cos(b))*cx,(R+r*Math.cos(b))*cy,r*Math.sin(b));n.push(Math.cos(b)*cx,Math.cos(b)*cy,Math.sin(b));}
    for(j=0;j<A;j++)for(i=0;i<B;i++){var q=j*(B+1)+i;idx.push(q,q+B+1,q+1,q+1,q+B+1,q+B+2);}return mesh({pos:new Float32Array(p),nor:new Float32Array(n),idx:new Uint16Array(idx)});})();
  [-2.75,2.75].forEach(function(x){var z=-4.6,ry=x<0?0.5:-0.5,base=0.55,sink=0.32,top=base+L-sink;   // 劍尖插入石座，刃口朝向御道
    var put=function(m,alb,r,met,t,s,rot){self.parts.push({m:m,alb:alb,r:r,met:met,M:M4.trs(t,(rot||0)+ry,0,s)});};
    put(box,stone,0.8,0,[x,base/2,z],[0.7,base,0.7]);put(box,gold,0.35,0.8,[x,base+0.015,z],[0.74,0.03,0.74]);put(box,stone,0.85,0,[x,0.06,z],[0.9,0.12,0.9]);
    self.parts.push({m:bl,alb:steel,r:0.16,met:0.95,M:M4.trs([x,top,z],ry,0,[1,1,1])});            // 劍身（劍尖朝下）
    put(sph,gold,0.3,0.85,[x,top+0.03,z],[0.2,0.045,0.13]);                                               // 金鐔
    put(cyl,red,0.7,0,[x,top+0.32,z],[0.042,0.56,0.042]);                                                // 朱柄
    [0.1,0.32,0.54].forEach(function(dy){put(cyl,gold,0.3,0.85,[x,top+dy+0.04,z],[0.05,0.035,0.05]);});    // 柄上金箍
    self.parts.push({m:tor,alb:gold,r:0.25,met:0.9,M:M4.trs([x,top+0.72,z],ry,0,[0.11,0.11,0.11])});   // 環首
    put(sph,lin(0xffd060),0.2,0.6,[x,top+0.72,z],[0.04,0.04,0.04]);                                       // 環中寶珠
    for(var k=0;k<5;k++)put(cyl,lin(0xb0161a),0.8,0,[x+(k-2)*0.018,top+0.48,z+0.02],[0.012,0.32,0.012]);});   // 紅穗
  this.parts.forEach(function(o){o.NM=M4.normal(o.M);});}
Swords.prototype.update=function(){};
Swords.prototype.draw=function(u,depth){if(!CFG.swords)return;gl.uniform1f(u.uSkin,0);if(!depth)gl.uniform1f(u.uUseTex,0);
  this.parts.forEach(function(o){gl.uniformMatrix4fv(u.uModel,false,o.M);if(!depth){gl.uniformMatrix3fv(u.uNM,false,o.NM);gl.uniform3fv(u.uAlb,o.alb);gl.uniform1f(u.uRough,o.r);gl.uniform1f(u.uMetal,o.met);}
    gl.bindVertexArray(o.m.vao);gl.drawElements(gl.TRIANGLES,o.m.n,gl.UNSIGNED_SHORT,0);});};
