  var s0=M.k[0][0],s1=lockEnd,sw=M.sway||[0,0];PL.fwd=ACTN.fwd0+(x<s0?sw[0]*ease(x/s0):x<s1?sw[0]+(sw[1]-sw[0])*ease((x-s0)/(s1-s0)):sw[1]*(1-ease((x-s1)/(1-s1))));   // 身體擰轉（小幅，不轉圈）
