  if(R.ph==='place'){faceTo(EU,RACK.pos[0],RACK.pos[1],dt);R.t-=dt;if(R.t<=0){EU.bow=0;WS.state='rack';WS.ret=null;if(typeof soulSay==='function')soulSay(EU,WS.w.name+'已歸位，主子放心。',2400);}return true;}
