var BOW_K=0.9;                                         // 弓的縮放（模型全長 1.25 公尺 × 0.9，配合皇上 152 公分身高）
var BW={ph:'idle',t:0,raise:0,draw:0,want:0,aim:0,el:0.035,pid:null,sx:0,sy:0,dx:0,dy:0,H0:null,rsh:-1,rel:-1,rhd:-1,nock:null,rest:null,M:null,A:null,shots:0,hits:0,pv:null};
