  var tIdle=[S[0]+(f[0]*h[0]+l[0]*h[2])*L,S[1]+h[1]*L,S[2]+(f[2]*h[0]+l[2]*h[2])*L],tAim=[S[0]+A[0]*L*0.97,S[1]+A[1]*L*0.97+0.03,S[2]+A[2]*L*0.97];
  W=ik2(R,W,comp,WS.sh,WS.el,WS.hl,lerp3(tIdle,tAim,k),1);var g=wpos(W,WS.hl);
