  var Yi=nrm([f[0]*0.45+l[0]*0.1,0.88,f[2]*0.45+l[2]*0.1]),Zi=nrm([-l[0],0,-l[2]]),Ya=nrm([-l[0]*0.12,1,-l[2]*0.12]),Za=[-A[0],-A[1],-A[2]];
  var Y=nrm(lerp3(Yi,Ya,k)),Z=lerp3(Zi,Za,k);Z=nrm(v_a(Z,Y,-v_d(Z,Y)));var X=v_c(Y,Z);
  var o=v_a(g,Z,0.035);BW.M=new Float32Array([X[0],X[1],X[2],0,Y[0],Y[1],Y[2],0,Z[0],Z[1],Z[2],0,o[0],o[1],o[2],1]);
  var T=bowTips(),ym=(T[0][1]+T[1][1])/2,brace=(T[0][2]+T[1][2])/2,rest=mPt(BW.M,[0.012,ym+0.03,0.0]),n0=mPt(BW.M,[0,ym,brace]);BW.rest=rest;
  if(!bowAiming()||BW.rhd<0){BW.nock=null;if(ARMS[2])W=ik2(R,W,comp,ARMS[2].sh,ARMS[2].el,ARMS[2].hd,v_a(g,Y,-0.1),0.7);return W;}
  // 右手：取箭（背後箭囊）→ 搭弦 → 依拉弓量往後拉到臉頰
  var RS=wpos(W,BW.rsh),Q=[RS[0]-f[0]*0.16,RS[1]+0.16,RS[2]-f[2]*0.16],tg;
  if(!BW.H0)BW.H0=wpos(W,BW.rhd);
  if(BW.ph==='nock'){var x=BW.t/0.5;tg=x<0.45?lerp3(BW.H0,Q,ease(x/0.45)):lerp3(Q,n0,ease((x-0.45)/0.55));}
  else{var dd=BW.ph==='loose'?BW.draw:BW.draw;tg=v_a(n0,Z,DRAW_L*dd);if(BW.ph==='loose'){var fx=Math.min(1,BW.t/0.12);tg=v_a(v_a(n0,Z,DRAW_L*BW.relD),Z,0.07*fx);tg=v_a(tg,[-l[0],0,-l[2]],0.05*fx);}}
  W=ik2(R,W,comp,BW.rsh,BW.rel,BW.rhd,tg,1);var hp=wpos(W,BW.rhd);
  if(ARMS[2])W=ik2(R,W,comp,ARMS[2].sh,ARMS[2].el,ARMS[2].hd,v_a(g,Y,-0.09),k);   /* 第二隻左手：握在弓把下方 */
  if(ARMS[3])W=ik2(R,W,comp,ARMS[3].sh,ARMS[3].el,ARMS[3].hd,v_a(v_a(hp,Y,-0.06),Z,-0.02),k);   /* 第二隻右手：貼著主手一起拉弦 */
