function arrowSound(k){sfx(function(){if(k==='ground')noise(0.07,{v:0.12,f:500,q:0.8,att:0.01});else{tone(k==='dummy'?240:330,0.09,{type:'square',v:0.07});noise(0.05,{v:0.1,f:1400,q:1,att:0.005});}});}
