  if(R.ph==='pick'){faceTo(EU,WS.gp[0],WS.gp[2],dt);R.t-=dt;if(R.T-R.t>0.35&&WS.state==='ground')WS.state='carry';if(R.t<=0){EU.bow=0;R.ph='carry';EJ.lp=null;}return true;}   /* 蹲下撿起、再站起來（附件 Crouch_To_Stand） */
