var DINE={seat:{id:'dine',name:'御膳椅',p:[1.0,7.9],yaw:0,hip:function(){return 0.5;},r:0.85},table:[0,0],kitchen:[4.4,7.4],serveAt:[0,0]};   /* 皇上指定位置（營火右前方），面朝營火 */
