function DW(o,dx,y,dz){var Y=DINE.seat.yaw,ax=[-Math.sin(Y),-Math.cos(Y)],az=[Math.cos(Y),-Math.sin(Y)];return [o[0]+dx*ax[0]+dz*az[0],y,o[1]+dx*ax[1]+dz*az[1]];}
