var TIER_NAME=['素膳','家常膳','珍饌','御宴'];
function dineScore(){var R=R0(),T=G.hist.filter(function(h){return h.day===G.day;}),g=T.filter(function(h){return h.good;}).length,b=T.filter(function(h){return h.bad;}).length,s=0;
  if(T.length)s+=3*(g-b*0.5)/T.length;if(R.dsDay===G.day)s+=1;if(typeof lsDone==='function'&&lsDone())s+=1;try{s+=(typeof dailyN==='function'?dailyN(dailyState()):0)*0.4;}catch(e){}
  var ind=G.ind||[50,50,50,50],avg=(ind[0]+ind[1]+ind[2]+ind[3])/4;s+=(avg-50)/25;return {s:Math.max(0,s),fisc:ind[0],avg:avg,good:g,bad:b,n:T.length};}
function dineMenu(){var sc=dineScore(),tier=sc.s>=5?3:sc.s>=3.2?2:sc.s>=1.6?1:0,n=Math.max(2,Math.min(6,2+Math.floor(sc.s*0.8))),why=[];
  if(sc.fisc<30&&tier>0){tier--;why.push('國庫吃緊，御膳房減了一等');}
  var L=[],pool=[];for(var t=tier;t>=0&&pool.length<n;t--)DISHES[t].forEach(function(d){pool.push(d.concat([t]));});
  for(var i=0;i<n&&i<pool.length;i++)L.push({name:pool[i][0],kind:pool[i][1],c1:pool[i][2],c2:pool[i][3],desc:pool[i][4],tier:pool[i][5],served:false,eaten:false,slot:i});
  return {day:G.day,tier:tier,dishes:L,score:sc,why:why};}
var DM={meet:null,menu:null,sv:{ph:'idle',i:0,t:0},eatT:0,eating:null};
function menuToday(){var R=R0();if(R.menu&&R.menu.day===G.day)return R.menu;return null;}
// ---------- 膳議（申時末，太監到中書省和群臣商議） ----------
function meetUpdate(dt){var R=R0();if(G.over||G.court==='on'||G.court==='wait')return false;
  if(!menuToday()&&G.hr>=16&&G.hr<19){if(!DM.meet){DM.meet={t:0,step:0,ph:'go'};if(typeof FJ!=='undefined'&&FJ.ph!=='idle')FJ.ph='idle';}}
  var M=DM.meet;if(!M)return false;if(G.hr>=17.2&&M.ph==='go'){M.ph='talk';M.step=99;}   /* 走不到也要在開飯前定案 */
  var o=LOC.office,tx=o[0]-1.4,tz=o[1]-0.2;
  if(M.ph==='go'){if(euGo(tx,tz,dt,Math.hypot(tx-EU.pos[0],tz-EU.pos[2])>5,0.9)||Math.hypot(tx-EU.pos[0],tz-EU.pos[2])<1.3&&EJ.direct>0){M.ph='talk';M.t=0;}return true;}
  if(M.ph==='talk'){faceTo(EU,o[0],o[1],dt);M.t+=dt;var sc=dineScore(),near=Math.hypot(PL.pos[0]-EU.pos[0],PL.pos[2]-EU.pos[2])<9,m0=MIN[0],m1=MIN[1],m2=MIN[2];
    var lines=[[EU,'諸位大人，今晚御膳該備些什麼？'],[m0,sc.good>=sc.bad?'皇上今日'+(sc.n?'奏議處置得當':'勤於政事')+'，該讓御膳房好好表現。':'今日幾件奏議處置欠妥，膳食從簡為宜。'],
      [m1,sc.fisc<30?'國庫正緊，菜色得省著些。':sc.avg>=60?'國泰民安，添幾道好菜也不為過。':'按祖制，量入為出便是。'],[m2,'臣以為不可因一時得失而奢儉無度，'+(sc.s>=3?'不過今日確實值得嘉許。':'還請皇上明日再接再厲。')],[EU,'那奴才就照諸位大人的意思，吩咐御膳房去了。']];
    var k=Math.floor(M.t/2.6);if(k!==M.step&&k<lines.length){M.step=k;var L=lines[k];if(L[0]&&typeof soulSay==='function')soulSay(L[0],L[1],2500);if(L[0]&&L[0].kind==='war'&&typeof warPlay==='function'&&Math.random()<0.6)warPlay(L[0],'secret');}
    if(M.t>2.6*lines.length||M.step===99){var menu=dineMenu();R.menu=menu;saveG();DM.meet=null;
      toast('📜 膳議定案：今晚「'+TIER_NAME[menu.tier]+'」共 '+menu.dishes.length+' 道——'+menu.dishes.map(function(d){return d.name;}).join('、')+(menu.why.length?'（'+menu.why.join('；')+'）':''),6500);}
    return true;}
  return false;}
// ---------- 上菜：一次一道，吃完再上下一道 ----------
function dineSeated(){return SIT.on&&SIT.seat&&SIT.seat.id==='dine';}
function mealPending(){return phase()[1]==='酉時'&&(G.court==='done'||G.court==='absent')&&!G.over&&typeof noonDone==='function'&&!noonDone();}
function onTable(){var m=menuToday();if(!m)return null;for(var i=0;i<m.dishes.length;i++){var d=m.dishes[i];if(d.served&&!d.eaten)return d;}return null;}
function serveJob(dt){var m=menuToday(),S=DM.sv;if(!m||!mealPending()||!dineSeated()){if(S.ph!=='idle'&&S.ph!=='wait'){S.ph='idle';}if(!dineSeated())S.carry=null;return false;}
  var next=null;   /* 一道接一道上，不等皇上吃完 */for(var i=0;i<m.dishes.length;i++)if(!m.dishes[i].served){next=m.dishes[i];break;}
  if(!next&&(S.ph==='idle'||S.ph==='fetch')){S.ph='idle';return false;}
  if(S.ph==='idle'){S.ph='fetch';S.d=next;EJ.lp=null;}
  var K=DINE.kitchen,T=DINE.serveAt;
  if(S.ph==='fetch'){if(euGo(K[0],K[1],dt,Math.hypot(K[0]-EU.pos[0],K[1]-EU.pos[2])>4,0.6)){S.ph='pick';S.t=0.7;EU.bow=0.4;}return true;}
  if(S.ph==='pick'){S.t-=dt;if(S.t<=0){EU.bow=0;S.carry=S.d;S.ph='carry';EJ.lp=null;}return true;}
  if(S.ph==='carry'){if(euGo(T[0],T[1],dt,false,0.45)){S.ph='place';S.t=0.9;EU.bow=0.45;}return true;}
  if(S.ph==='place'){faceTo(EU,DINE.table[0],DINE.table[1],dt);S.t-=dt;if(S.t<0.45&&S.carry){S.carry.served=true;S.carry=null;saveG();var d=S.d,first=m.dishes.indexOf(d)===0;
      if(typeof soulSay==='function')soulSay(EU,(first?'主子，今晚是「'+TIER_NAME[m.tier]+'」。':'')+'這道是「'+d.name+'」——'+d.desc,3400);}
    if(S.t<=0){EU.bow=0;S.ph='idle';}return true;}
  S.ph='idle';return false;}
