// ---------- 鏡頭：移動時自動回到皇上背後（手動轉鏡頭後 1.5 秒內不干擾） ----------
var CAMR={th:null,manual:0};
function camRecenter(dt){if(typeof cam==='undefined'||!cam||window.__CT||UI.mode!=='free'||G.court==='on'||!CFG.follow){CAMR.th=null;return;}
  if(CAMR.th!=null&&Math.abs(cam.theta-CAMR.th)>1e-4)CAMR.manual=1.5;CAMR.manual=Math.max(0,CAMR.manual-dt);
  var v=PL.vs||0;if(CAMR.manual<=0&&v>0.4&&!SIT.on&&!bowAiming()&&!(typeof WJ!=='undefined'&&WJ.on)){var want=PL.yaw+Math.PI,d=Math.atan2(Math.sin(want-cam.theta),Math.cos(want-cam.theta));
    if(Math.abs(d)<2.4)cam.theta+=d*Math.min(1,dt*(0.6+1.4*Math.min(1,v/PL.vRun)));}   /* 朝鏡頭方向倒退走時不硬轉 */
  CAMR.th=cam.theta;}
