function mcPlayKey(a,k){if(!a||a.hidden)return;if(a.kind==='war'){var n=mcWarClip(k);if(n)a.play(n,0.25);return;}var rk=a===PL?'asura':a===EU?'drake':a===PR?'corps':null;if(!rk)return;var nm=mcAdd(a,rk,k);if(!nm)return;a.speed=0;a.once=nm;a.play(nm,0.25);a.t=0;}
function mcIdle(a){return a&&!a.hidden&&!a.once&&(a.speed||0)<0.08&&(a.kind!=='war'||a.clip==='idle');}
