  var _sc=sampleClip;sampleClip=function(A,name,t,T,R,S){var an=A.anims[name];if(an&&an.mc){_sc(A,'idle',t,T,R,S);mcApply(A,an,t,T,R);return;}return _sc.apply(this,arguments);};
