  if(typeof bowAll==='function'){var _ba=bowAll;bowAll=function(a,ms){_ba.apply(this,arguments);if(a>0.3){MIN.concat([EU]).forEach(function(m,i){setTimeout(function(){if(mcPlay(m,'bow'))m.bow=a*0.25;},120+i*160);});}};}
  // 說話時的手勢：應答、指引、呼喚、揮手
  if(typeof soulSay==='function'){var _ss=soulSay;soulSay=function(a,t,ms){var r=_ss.apply(this,arguments);if(a&&a!==PL&&mcIdle(a)&&Math.random()<0.45){var s=String(t||''),c=/臣遵旨|遵命|是，|奴才這就|明白/.test(s)?'respond':/請|這邊|那邊|往/.test(s)?'guide':/皇上！|陛下！|主子！|來人/.test(s)?'call':/告退|退下|再會/.test(s)?'bye':pick(['respond','guide','respond','call']);if(G.court==='on'&&c!=='respond')c='respond';mcPlay(a,c);}return r;};}
  // 喝采：大臣高舉雙手／揮手，太子跳一段舞
  if(typeof everyone==='function'){var _ev=everyone;everyone=function(c,ms){if(c==='cheer'){MIN.forEach(function(m){if(mcIdle(m)&&Math.random()<0.5)setTimeout(function(){mcPlay(m,pick(['raise-up-both-hands','wave-both-hands','raise-up-right-hand']));},200+Math.random()*500);});
      if(mcIdle(PR)&&Math.random()<0.6)setTimeout(function(){mcPlay(PR,'dance-short','normal');},400);}return _ev.apply(this,arguments);};}
