  [].forEach.call(el.querySelectorAll('[data-pat]'),function(b){b.onclick=function(){CE.P.pat=+b.dataset.pat;ceRebuild();ceRender();};});
  [].forEach.call(el.querySelectorAll('[data-sk]'),function(b){b.onclick=function(){CE.P.skirt=+b.dataset.sk;ceRebuild();ceRender();};});
