// ---------- 皇上跳起來撞到人：把人撞開 ----------
var KB={cool:{}};
function kbUpdate(dt){var L=[EU,PR].concat(MIN||[]);
  L.forEach(function(a){if(!a||!a.pos)return;var k=a.kb;if(k){var s=Math.min(1,dt*1.0);a.pos[0]+=k.vx*dt;a.pos[2]+=k.vz*dt;k.vx*=Math.exp(-dt*5);k.vz*=Math.exp(-dt*5);k.t-=dt;if(k.t<=0)a.kb=null;}});
  if(typeof hero!=='undefined'&&hero&&hero.kb){var hk=hero.kb;hero.pos[0]+=hk.vx*dt;hero.pos[2]+=hk.vz*dt;hk.vx*=Math.exp(-dt*5);hk.vz*=Math.exp(-dt*5);hk.t-=dt;if(hk.t<=0)hero.kb=null;}
  if(!JMP.on||JMP.y>1.1)return;var now=performance.now();
  var hit=function(a,r,isRab){var p=a.pos,dx=p[0]-PL.pos[0],dz=p[2]-PL.pos[2],d=Math.hypot(dx,dz);if(d>r||d<1e-3)return;var id=isRab?'rab':(a.id||a.name);if(KB.cool[id]&&now-KB.cool[id]<900)return;KB.cool[id]=now;
    var sp=(isRab?3.2:2.6)+(PL.vs||0)*0.6;a.kb={vx:dx/d*sp,vz:dz/d*sp,t:0.55};buzz(18);shake(0.02,0.18);
    if(typeof dustBurst==='function')dustBurst([p[0],0.05,p[2]],10,1.6);if(typeof smp==='function')smp('drop',0.45,0.7);
    if(!isRab){if(a.A&&a.A.anims.hit&&!a.once){a.once='hit';a.play('hit',0.08);a.t=0;}
      if(typeof soulSay==='function')soulSay(a,pick(a===EU?['哎喲——主子饒命！','主子當心腳下！','奴才的老腰……']:a===PR?['父皇這是做什麼！','兒臣……站不穩了。']:['陛下！臣站不住了！','哎呀，失禮了失禮了。']),2200);}
    else{if(typeof rabEvent==='function')try{rabEvent('jump');}catch(e){}}};
  L.forEach(function(a){if(a&&a.pos&&!a.hidden)hit(a,0.75,false);});
  if(typeof hero!=='undefined'&&hero&&hero.pos)hit(hero,0.55,true);}
// ---------- 白兔：入夜後靠到柴火旁取暖、趴著休息 ----------
function rabNight(){var h=G.hr;return (h>=19.5||h<5)&&G.court!=='on'&&CFG.fire!==0;}
function rabWarmSpot(){var a=-2.4+Math.sin(G.day*1.7)*0.5;return [FIRE_POS[0]+Math.cos(a)*1.25,FIRE_POS[2]+Math.sin(a)*1.25];}
