  var phrase=Math.floor(BGM.ph/8)%4,deg=[0,2,4,3,2,1,0,4][(BGM.ph+phrase*3)%8]+(phrase===2?2:0),oct=Math.random()<0.15?2:1,f=base*Math.pow(2,BGM_SC[deg%5]/12)*(deg>=5?2:1)*oct;
  if(Math.random()<0.82)bgmPluck(a,f,night?0.05:0.07);if(BGM.ph%8===0)bgmPluck(a,base/2,0.05);if(Math.random()<0.18)bgmPluck(a,f*1.5,0.03,0.12);
