var MON=[['psx-killer-04','面具殺手'],['psx-killer-05','雨衣怪客'],['psx-killer-06','屠夫'],['psx-killer-07','小丑'],['psx-monster','怪物'],['psx-monster-03','異形'],['psx-monster-04','沼澤怪'],['psx-monster-05','惡鬼']];
var COP_M={m:['psx-18-police','警察'],f:['psx-17-female-police','女警']},COP_COST=200,COP_FILL=30;
var BOOTH={p:[-6.95,14.0]},CAPR=14.5,GATE_S=6.2,COP_MAX=10;
// ---------- 幾何：沿大街的座標 ----------
function stU(){var a=ROAD.a,b=ROAD.b,l=Math.hypot(b[0]-a[0],b[1]-a[1]);return [(b[0]-a[0])/l,(b[1]-a[1])/l];}
function roadPt(s,off){var u=stU();return [ROAD.a[0]+u[0]*s-u[1]*off,ROAD.a[1]+u[1]*s+u[0]*off];}
function gY(x,z){return typeof terrH==='function'&&CFG.terrain?terrH(x,z):0;}
function inCap(x,z){return Math.hypot(x,z)<CAPR-0.3;}          // 皇都範圍（v73 擴大到半徑 14.5 公尺）
function keepOut(p,r){var d=Math.hypot(p[0],p[1]);if(d<r){var k=r/(d||1);p[0]*=k;p[1]*=k;}}
function stNight(){var h=G.hr%24;return h>=19.5||h<4.5;}
function stDay(){var h=G.hr%24;return h>=6&&h<18.5;}
// ---------- 國況：依四項指標與最近的決策 ----------
function stMood(){var ind=G.ind||[50,50,50,50],avg=(ind[0]+ind[1]+ind[2]+ind[3])/4,H=(G.hist||[]).slice(-6),g=0,b=0;H.forEach(function(h){if(h.good)g++;if(h.bad)b++;});
  var low=0;for(var i=1;i<4;i++)if(ind[i]<ind[low])low=i;return {avg:avg,g:g,b:b,low:low,score:(avg-50)+g*4-b*5,last:H[H.length-1]||null,lastBad:H.filter(function(h){return h.bad;}).pop()||null};}
function stBad(){var M=stMood();return Math.max(0,Math.min(1,(55-M.avg)/35+M.b*0.08-M.g*0.05));}
// ---------- 人物 ----------
function npcNew(m,name,p,kind){return {m:m,n:name,p:p.slice(),yaw:Math.random()*6.28,clip:'idle',t:Math.random()*3,sp:0,tg:null,st:'idle',k:kind,w:0,J:null,ft:-1,hide:false};}
function npcGo(n,tx,tz,dt,spd,stop){var dx=tx-n.p[0],dz=tz-n.p[1],d=Math.hypot(dx,dz);if(d<=(stop||0.3)){n.v=(n.v||0)*Math.max(0,1-dt*6);n.sp=n.v<0.12?0:n.v;if(n.sp>0&&d>1e-3){n.p[0]+=dx/d*Math.min(n.sp*dt,d);n.p[1]+=dz/d*Math.min(n.sp*dt,d);}return true;}
  n.v=(n.v||0)+(Math.min(spd,d*2.2)-(n.v||0))*Math.min(1,dt*3.5);var v=Math.min(n.v,d/dt);n.p[0]+=dx/d*v*dt;n.p[1]+=dz/d*v*dt;n.sp=v;var ty=Math.atan2(dx,dz),dy=Math.atan2(Math.sin(ty-n.yaw),Math.cos(ty-n.yaw));n.yaw+=dy*Math.min(1,dt*5);return false;}
function npcFace(n,x,z,dt){var ty=Math.atan2(x-n.p[0],z-n.p[1]),dy=Math.atan2(Math.sin(ty-n.yaw),Math.cos(ty-n.yaw));n.yaw+=dy*Math.min(1,dt*6);}
function npcAnim(n,dt,act){var MA=HUM.m2m;if(!MA)return;var c=n.sp>2.2?'run':n.sp>0.15?'walk':(act||'idle');if(!MA.anims[c])c='idle';
  if(c!==n.clip){n.clip=c;n.t=0;}var nat=c==='walk'?1.25:c==='run'?3.0:0;n.t+=nat?dt*Math.max(0.6,Math.min(1.8,n.sp/nat)):dt;}
function npcDraw(u,depth,n){if(n.hide)return;var m=vbModel(n.m);if(!m)return;var MA=HUM.m2m,an=MA.anims[n.clip]||MA.anims.idle;
  var far=Math.hypot(n.p[0]-PL.pos[0],n.p[1]-PL.pos[2])>16;if(n.ft!==VB.fr&&(!far||!n.J||(VB.fr+n.p[0]*7|0)%3===0)||!n.J){n.ft=VB.fr;n.J=mcPose(m,MA.anims[n.clip]?n.clip:'idle',n.t%an.dur,[n.p[0],gY(n.p[0],n.p[1]),n.p[1]],n.yaw,n.h||1.72);}
  gl.uniform1f(u.uSkin,1);gl.uniformMatrix4fv(u.uB,false,n.J);gl.uniformMatrix4fv(u.uModel,false,M4.ident());var k=CFG.bright*(n.dim||1);
  if(!depth){gl.uniformMatrix3fv(u.uNM,false,M4.normal(M4.ident()));gl.uniform1f(u.uRough,0.75);gl.uniform1f(u.uMetal,0);
    if(m.tex){gl.uniform1f(u.uUseTex,1);gl.uniform1f(u.uLinT,1);gl.activeTexture(gl.TEXTURE3);gl.bindTexture(gl.TEXTURE_2D,m.tex);gl.uniform3fv(u.uTint,[k,k,k]);}else if(m.V.c){gl.uniform1f(u.uUseTex,3);gl.uniform3fv(u.uTint,[k,k,k]);}else{gl.uniform1f(u.uUseTex,0);gl.uniform3fv(u.uAlb,[0.6,0.6,0.6]);}}
  gl.bindVertexArray(depth?m.dvao:m.vao);gl.drawElements(gl.TRIANGLES,m.n,m.it,0);if(!depth){gl.uniform1f(u.uLinT,0);gl.uniform1f(u.uUseTex,0);gl.uniform3fv(u.uTint,[CFG.bright,CFG.bright,CFG.bright]);}gl.uniform1f(u.uSkin,0);}
function near(n,r){return Math.hypot(n.p[0]-PL.pos[0],n.p[1]-PL.pos[2])<r;}
function plFwd(){var dx=PL.pos[0]-ST.hd[0],dz=PL.pos[2]-ST.hd[1],d=Math.hypot(dx,dz);if(d>0.02){var a=Math.atan2(dx,dz),c=ST.fwa==null?a:ST.fwa,dd=Math.atan2(Math.sin(a-c),Math.cos(a-c));ST.fwa=c+Math.max(-0.12,Math.min(0.12,dd));ST.fw=[Math.sin(ST.fwa),Math.cos(ST.fwa)];ST.hd=[PL.pos[0],PL.pos[2]];}   /* 方向慢慢轉，隨行的人不會甩來甩去 */return ST.fw||[Math.sin(PL.yaw),Math.cos(PL.yaw)];}
// ---------- 頭上的話（跟著人物移動的對話泡泡） ----------
function bubble(n,txt,ms,cls){var e=document.createElement('div');e.className='stBub'+(cls?' '+cls:'');e.textContent=txt;document.body.appendChild(e);var b={n:n,e:e,t:ms/1000};ST.bub.push(b);while(ST.bub.length>4){var o=ST.bub.shift();o.e.remove();}return b;}
function bubUpdate(dt){var VP=window.__VP,cv=document.querySelector('canvas');ST.bub=ST.bub.filter(function(b){b.t-=dt;if(b.t<=0||!VP||!cv){b.e.remove();return false;}
  var n=b.n,x=n.p?n.p[0]:n.pos[0],z=n.p?n.p[1]:n.pos[2],y=(n.p?gY(x,z):(n.y||0))+2.05,cx=VP[0]*x+VP[4]*y+VP[8]*z+VP[12],cy=VP[1]*x+VP[5]*y+VP[9]*z+VP[13],cw=VP[3]*x+VP[7]*y+VP[11]*z+VP[15];
  if(cw<0.1){b.e.style.display='none';return true;}var r=cv.getBoundingClientRect(),hw=(b.e.offsetWidth||80)/2+4;b.e.style.display='';b.e.style.left=Math.max(hw,Math.min(innerWidth-hw,r.left+(cx/cw+1)/2*r.width))+'px';b.e.style.top=(r.top+(1-cy/cw)/2*r.height)+'px';b.e.style.opacity=Math.min(1,b.t*2);return true;});}
// ---------- 鳴鑼開道（合成銅鑼聲） ----------
function gong(v){if(!CFG.sfx||!FX.ac||FX.ac.state!=='running')return;try{var a=FX.ac,t=a.currentTime,g=a.createGain();g.connect(a.destination);g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(0.35*(v||1),t+0.02);g.gain.exponentialRampToValueAtTime(0.0001,t+2.2);
  [[196,1],[263,0.6],[389,0.4],[530,0.25],[742,0.12]].forEach(function(q){var o=a.createOscillator(),gg=a.createGain();o.type='sine';o.frequency.setValueAtTime(q[0]*1.02,t);o.frequency.exponentialRampToValueAtTime(q[0],t+0.6);gg.gain.value=q[1];o.connect(gg);gg.connect(g);o.start(t);o.stop(t+2.3);});}catch(e){}}
// ---------- 陳情內容：依國況與最近的決策 ----------
var ST_LOW=[['皇上，米價、鹽價一漲再漲，稅也重，小民快撐不住了！','國庫要是空了，修橋鋪路誰出錢？請皇上量入為出。'],
  ['皇上，街坊的冤屈沒人聽，懇請為小民作主！','家裡斷炊好幾天了，求皇上開倉賑濟！'],
  ['衙門辦個路引要跑五趟，官老爺推來推去，請皇上整頓！','報案三個月了還沒下文，吏治該管管了！'],
  ['朝廷今天說東、明天說西，小民不知該聽誰的。','各部互相扯後腿，苦的是百姓，請皇上居中協調！']];
function petition(M,who){var L=M.lastBad,ind=G.ind||[50,50,50,50];
  if(M.score>=8)return [['皇上聖明！','託皇上的福，今年日子好過多了！','吾皇萬歲！小民支持皇上！','皇上辛苦了，要保重龍體啊！'][Math.floor(Math.random()*4)]+(M.last?'「'+M.last.pick.slice(0,14)+'」這事辦得好！':''),'good'];
  if(M.score<=-8)return [[L?'「'+L.pick.slice(0,14)+'」這是什麼決定？我們不服！':'我們不服！','昏君誤國！還我公道！','再這樣下去，日子沒法過了！','抗議！抗議！請皇上收回成命！'][Math.floor(Math.random()*4)],'bad'];
  var a=ST_LOW[M.low];return [a[Math.floor(Math.random()*a.length)]+'（'+IND[M.low]+' '+Math.round(ind[M.low])+'）','mid'];}
// ---------- 居民 ----------
function stN(){return SETS.stN==null?24:SETS.stN;}
function resSpawn(){ST.npc=[];var sv=(G.serv||[]).concat(G.jail||[]).map(function(x){return x.m;}),pool=RES_M.map(function(m,i){return i;}).filter(function(i){return sv.indexOf(RES_M[i])<0;});
  for(var i=0;i<stN();i++){var k=pool[(i+ST.day*5)%pool.length],p=i%2?roadPt(GATE_S+2+Math.random()*34,(Math.random()-0.5)*3):mktPt();var n=npcNew(RES_M[k],RES_N[k],p,'res');n.h=1.62+Math.random()*0.2;ST.npc.push(n);}}
function mktPt(){return [-17.2+Math.random()*12.4,15.3+Math.random()*2.0];}
function resTarget(n){var r=Math.random();if(r<0.35&&typeof mktStalls==='function'){var S=mktStalls().filter(function(q){return q.cust;}),q=S[Math.floor(Math.random()*S.length)];if(!q){n.tg=mktPt();n.shop=null;n.w=2;return;}n.tg=[q.cust[0]+(Math.random()-0.5)*0.5,q.cust[1]+(Math.random()-0.5)*0.3];n.shop=q;}else{n.shop=null;n.tg=r<0.7?roadPt(GATE_S+2+Math.random()*34,(Math.random()-0.5)*3.2):mktPt();}n.w=1+Math.random()*4;}
function resUpdate(n,dt,M){if(n.irr)return;resStep(n,dt,M);if(!n.hide)keepOut(n.p,CAPR+0.2);}
function resStep(n,dt,M){var dP=Math.hypot(n.p[0]-PL.pos[0],n.p[1]-PL.pos[2]),out=!inCap(PL.pos[0],PL.pos[2]),act='idle';
  if(n.st==='home'){if(!n.tg)n.tg=roadPt(52+Math.random()*10,(Math.random()-0.5)*2);if(npcGo(n,n.tg[0],n.tg[1],dt,1.4,0.5))n.hide=true;npcAnim(n,dt);return;}
  if(out&&dP<9&&!UI.locked){                                   // 發現皇上：圍過來
    if(n.st!=='crowd'){n.st='crowd';n.kn=M.score>-8?1.6+Math.random():0;n.ang=Math.random()*6.28;if(Math.random()<0.5)bubble(n,M.score>-8?'皇上駕到！':'是皇上！',1600);}
    var R=ST.tour?2.9:2.0,ang=n.ang,tx=PL.pos[0]+Math.sin(ang)*R,tz=PL.pos[2]+Math.cos(ang)*R;
    var arrived=npcGo(n,tx,tz,dt,dP>4?2.6:1.3,0.35);if(arrived){npcFace(n,PL.pos[0],PL.pos[2],dt);
      if(n.kn>0){n.kn-=dt;act='kneel';}else act=M.score>=8?(Math.random()<0.002?'cheer':(n.clip==='cheer'?'cheer':'clap')):M.score<=-8?'talk':'talk';}
    npcAnim(n,dt,act);return;}
  if(n.st==='crowd'){n.st='idle';n.tg=null;}
  if(n.st==='wait'){n.w-=dt;n.sp=0;if(n.w<=0){resTarget(n);n.st='walk';}}
  else{if(!n.tg)resTarget(n);n.st='walk';if(npcGo(n,n.tg[0],n.tg[1],dt,1.1,0.4)){n.st='wait';n.w=2+Math.random()*6;n.idA=n.shop?['talk','interact','pickupT','nod'][Math.floor(Math.random()*4)]:['idle','idle2','talk','idle','clap','yes'][Math.floor(Math.random()*6)];if(n.shop)n.yaw=n.shop.yaw+Math.PI;}}
  npcAnim(n,dt,n.st==='wait'?n.idA:'idle');}
function resSpeak(dt,M){if(SETS.stBub===0)return;ST.say-=dt;if(ST.say>0)return;var C=ST.npc.filter(function(n){return n.st==='crowd'&&!n.hide&&near(n,3.5)&&!(n.kn>0);});if(!C.length)return;
  var n=C[Math.floor(Math.random()*C.length)],q=petition(M,n);bubble(n,n.n+'：'+q[0],3600,q[1]);ST.say=2.6+Math.random()*1.5;
  if(q[1]==='bad'&&Math.random()<0.3)setTimeout(function(){var o=C[Math.floor(Math.random()*C.length)];if(o!==n)bubble(o,'對！我們不服！',1800,'bad');},900);}
// ---------- 聖駕出巡：太監前導、鳴鑼開道，巡捕護駕 ----------
function tourUpdate(dt){var out=!inCap(PL.pos[0],PL.pos[2])&&roadS(PL.pos[0],PL.pos[2])>GATE_S-0.3&&Math.abs(roadOff(PL.pos[0],PL.pos[2]))<8&&Math.hypot(PL.pos[0],PL.pos[2])<90,   /* v75：出了城門才算出巡 */on=out&&stDay()&&G.court!=='on'&&!G.over&&EU&&!EU.hidden;
  if(on&&!ST.tour){ST.tour=true;ST.ep=[EU.pos[0],EU.pos[2]];ST.shout=0.5;toast('🥁 聖駕出巡——總管太監在前開道，巡捕隨行護駕。',2600);}
  if(!on&&ST.tour){ST.tour=false;}
  if(EU&&Math.hypot(EU.pos[0],EU.pos[2])>9.6)EU.y=gY(EU.pos[0],EU.pos[2]);else if(EU&&ST.euY){EU.y=0;}ST.euY=EU&&Math.hypot(EU.pos[0],EU.pos[2])>9.6;
  if(!ST.tour)return;var f=plFwd(),run=(PL.vs||0)>2,_eo=typeof euTourOff==='function'?euTourOff(f):[f[0]*2.6-f[1]*0.7,f[1]*2.6+f[0]*0.7],tx=PL.pos[0]+_eo[0],tz=PL.pos[2]+_eo[1],dx=tx-ST.ep[0],dz=tz-ST.ep[1],d=Math.hypot(dx,dz);
  if(d>25){ST.ep=[tx,tz];d=0;}ST.eus=(ST.eus||0)+(Math.min(d*1.8,run?4.0:2.2)-(ST.eus||0))*Math.min(1,dt*3);var sp=ST.eus;if(d>0.15){ST.ep[0]+=dx/d*sp*dt;ST.ep[1]+=dz/d*sp*dt;}
  EU.pos=[ST.ep[0],0,ST.ep[1]];EU.y=gY(ST.ep[0],ST.ep[1]);EU.speed=d>0.15?sp:0;var fy=d>0.25?Math.atan2(dx,dz):Math.atan2(f[0],f[1]);EU.yaw+=Math.atan2(Math.sin(fy-EU.yaw),Math.cos(fy-EU.yaw))*Math.min(1,dt*5);
  var want=EU.speed>2.2?'jog':EU.speed>0.2?'walk':'idle';if(EU.A&&EU.A.anims[want]&&EU.clip!==want&&!EU.once)EU.play(want,0.2);
  ST.shout-=dt;if(ST.shout<=0){var any=ST.npc.some(function(n){return !n.hide&&near(n,10);})||ST.mon.some(function(n){return !n.hide&&near(n,12);});
    ST.shout=any?6:11;bubble(EU,['皇上駕到——閒雜人等迴避！','肅靜——迴避——','聖駕在此，不得衝撞！','皇上駕到——'][Math.floor(Math.random()*4)],2400,'eu');}
  if(ST.gong>0){ST.gong-=dt;if(ST.gong<=0){gong(1);ST.gong=-1;setTimeout(function(){gong(0.8);},650);}}
  // 開路：擋在聖駕正前方的居民往路邊讓
  if(!window.__V80)ST.npc.forEach(function(n){if(n.hide)return;var rx=n.p[0]-PL.pos[0],rz=n.p[1]-PL.pos[2],ah=rx*f[0]+rz*f[1],sd=-rx*f[1]+rz*f[0];if(ah>-0.5&&ah<4&&Math.abs(sd)<1.6&&!n.yld&&n.st!=='crowd'){var s=sd>=0?1:-1;n.yld={to:[n.p[0]-f[1]*s*(1.8-Math.abs(sd)),n.p[1]+f[0]*s*(1.8-Math.abs(sd))],t:2.5};}});}
// ---------- 巡捕 ----------
function copList(){if(!G.cops){G.cops=[{k:'m',st:100,rest:-1}];}return G.cops;}
function copSync(){var L=copList();while(ST.cop.length<L.length){var c=L[ST.cop.length],m=COP_M[c.k],p=roadPt(GATE_S+1,0);ST.cop.push(npcNew(m[0],m[1],p,'cop'));}ST.cop.length=L.length;}
function copPost(i){var row=Math.floor(i/2),side=i%2?1:-1;return roadPt(GATE_S+1.4+row*1.3,side*1.75);}
function copUpdate(dt,M){copSync();var L=copList(),esc=0,u=stU(),hr=dt*19/(Math.max(1,CFG.dayMin)*60);
  ST.cop.forEach(function(n,i){var c=L[i];n.c=c;if(c.rest>=0&&G.day<=c.rest){n.hide=true;n.p=roadPt(GATE_S+1,0);return;}if(c.rest>=0){c.rest=-1;c.st=100;saveG();}n.hide=false;
    var post=copPost(i),tgt=null,spd=1.3,act='idle';
    var mon=ST.mon.filter(function(m){return !m.hide&&!m.flee&&Math.hypot(m.p[0]-post[0],m.p[1]-post[1])<11;}).sort(function(a,b){return Math.hypot(a.p[0]-n.p[0],a.p[1]-n.p[1])-Math.hypot(b.p[0]-n.p[0],b.p[1]-n.p[1]);})[0];
    if(mon&&c.st>0){tgt=mon.p;spd=2.9;if(Math.hypot(mon.p[0]-n.p[0],mon.p[1]-n.p[1])<1.25){tgt=n.p;n.sp=0;npcFace(n,mon.p[0],mon.p[1],dt);act=(ST.t*1.3+i)%2<1?'slash':'hit';fight(n,c,mon,dt);}}
    else if(ST.tour&&esc<4&&c.st>0){var f=plFwd(),sl=[[1.3,1.4],[1.3,-1.4],[-1.6,1.2],[-1.6,-1.2]][esc++];tgt=[PL.pos[0]+f[0]*sl[0]-f[1]*sl[1],PL.pos[2]+f[1]*sl[0]+f[0]*sl[1]];spd=Math.max(1.4,(PL.vs||0)+0.8);c.st=Math.max(0,c.st-hr*1.5);}
    else{tgt=post;}
    if(npcGo(n,tgt[0],tgt[1],dt,spd,0.3)){if(tgt===post){var ty=Math.atan2(u[0],u[1]);n.yaw+=Math.atan2(Math.sin(ty-n.yaw),Math.cos(ty-n.yaw))*Math.min(1,dt*4);}else if(tgt!==n.p)npcFace(n,PL.pos[0],PL.pos[2],dt);}
    c.st=Math.max(0,c.st-hr*0.6);if(c.st<=0&&c.rest<0){c.rest=G.day+1;saveG();toast('👮 '+n.n+(i+1)+'號體力用盡，回家休息一天。',2600);}
    npcAnim(n,dt,c.st<25?'idle2':act);});}
// ---------- 夜間怪客：依國況決定數量、範圍與行為；永遠不進皇都 ----------
function monSpawn(){var b=stBad(),M=stMood(),n=SETS.stMon===0?0:Math.round(2+b*10),far=14+b*30;ST.mon=[];ST.reach=far;
  for(var i=0;i<n;i++){var t=MON[(i*3+G.day)%MON.length],s=GATE_S+4+Math.random()*(far+8),p=roadPt(s,(Math.random()-0.5)*6);keepOut(p,CAPR+1.2);var m=npcNew(t[0],t[1],p,'mon');
    m.act=b>0.6&&Math.random()<0.5?'riot':M.low===0&&(t[0]==='psx-killer-06'||t[0]==='psx-killer-07')?'vandal':M.low===2&&t[0]==='psx-monster-05'?'protest':M.low===1&&b>0.3?'stalk':Math.random()<0.4?'protest':'roam';
    m.k2=1.1+Math.random()*0.9;m.h=1.72*m.k2;m.hp=60+50*m.k2;m.dim=0.85;ST.mon.push(m);}}
function monFlee(m,why){if(m.flee)return;m.flee=1;m.tg=roadPt(60+Math.random()*10,(Math.random()-0.5)*4);bubble(m,['哇——快逃！','可惡……','撤！'][Math.floor(Math.random()*3)],1600,'bad');if(why)bubble(ST.cop.filter(function(c){return !c.hide;})[0]||EU,why,1800);}
function monUpdate(m,dt){if(m.hide||m.irr)return;var dP=Math.hypot(m.p[0]-PL.pos[0],m.p[1]-PL.pos[2]),act='idle';
  if(m.flee){if(npcGo(m,m.tg[0],m.tg[1],dt,3.2,0.6))m.hide=true;keepOut(m.p,CAPR+1.2);npcAnim(m,dt);return;}
  if(m.foe){var F=m.foe;if(F.hide||!F.c||F.c.st<=0||Math.hypot(F.p[0]-m.p[0],F.p[1]-m.p[1])>9){m.foe=null;}else{if(npcGo(m,F.p[0],F.p[1],dt,2.1,1.0)){npcFace(m,F.p[0],F.p[1],dt);act=(ST.t*1.1)%2<1?'slash':'hit';}keepOut(m.p,CAPR+1.2);npcAnim(m,dt,act);knifeHit(m);return;}}
  if(!m.foe&&m.act!=='riot'){var cc=ST.cop.filter(function(c){return !c.hide&&c.c&&c.c.st>0&&Math.hypot(c.p[0]-m.p[0],c.p[1]-m.p[1])<7;})[0];if(cc){m.foe=cc;if(Math.random()<0.6)bubble(m,['條子！上！','先收拾巡捕！','擋我者死！'][Math.floor(Math.random()*3)],1600,'bad');}}
  if(m.act==='riot'&&dP<9&&!inCap(PL.pos[0],PL.pos[2])){m.tg=null;if(npcGo(m,PL.pos[0],PL.pos[2],dt,2.3,0.9)){if(!m.cd||m.cd<=0){m.cd=2.5;plBump(m);}}m.cd=(m.cd||0)-dt;}
  else if(m.act==='stalk'&&dP<14){if(dP>4)npcGo(m,PL.pos[0],PL.pos[2],dt,1.0,4);else{m.sp=0;npcFace(m,PL.pos[0],PL.pos[2],dt);act='idle2';}if(Math.random()<dt*0.12)bubble(m,['……','嘿嘿嘿……','皇上，夜路要小心喔。'][Math.floor(Math.random()*3)],1800,'bad');}
  else if(m.act==='protest'){if(!m.tg)m.tg=roadPt(GATE_S+3+Math.random()*3,(Math.random()-0.5)*3);if(npcGo(m,m.tg[0],m.tg[1],dt,1.2,0.4)){act=Math.random()<0.5?'knock':'talk';if(m.clip==='knock'||m.clip==='talk')act=m.clip;npcFace(m,ROAD.a[0],ROAD.a[1],dt);if(Math.random()<dt*0.18)bubble(m,['開門！給個說法！','暴政必亡！','還我血汗錢！','朝廷不管，我們自己管！'][Math.floor(Math.random()*4)],2200,'bad');}}
  else if(m.act==='vandal'){var S=MKT.st[(ST.mon.indexOf(m))%MKT.st.length];var cu=S.cust||[S.p[0],S.p[1]+1.0];if(npcGo(m,cu[0],cu[1],dt,1.4,0.4)){act='chop';npcFace(m,S.p[0],S.p[1],dt);if(Math.random()<dt*0.1)bubble(m,['砸了！通通砸了！','稅這麼重，還做什麼生意！'][Math.floor(Math.random()*2)],2000,'bad');}}
  else{if(!m.tg||npcGo(m,m.tg[0],m.tg[1],dt,1.0,0.5)){m.tg=Math.random()<0.25?mktPt():roadPt(GATE_S+4+Math.random()*(ST.reach||20),(Math.random()-0.5)*7);}}
  keepOut(m.p,CAPR+1.2);npcAnim(m,dt,act);knifeHit(m);}
// 皇上的飛刀射中：重創，血量歸零就逃走
function knifeHit(m){if(typeof KN!=='undefined')KN.forEach(function(k){if(k.st==='fly'&&!k._mh&&Math.hypot(k.p[0]-m.p[0],k.p[2]-m.p[1])<0.45+0.25*(m.k2||1)&&k.p[1]-gY(m.p[0],m.p[1])<1.2*(m.h||1.72)){k._mh=1;m.hp=(m.hp||60)-70;if(typeof smp==='function')smp('success',0.4);if(m.hp<=0)monFlee(m);else bubble(m,'嗚！',800,'bad');}});}
// 巡捕與怪客交手：體力與血量互相消耗
function fight(n,c,m,dt){if(m.flee)return;m.foe=m.foe||n;var k=Math.max(0.35,c.st/100);m.hp-=dt*(16+14*k);c.st=Math.max(0,c.st-dt*(1.2+1.3*(m.k2||1)));if(Math.random()<dt*0.5)bubble(n,[n.n+'：站住！不許作亂！','束手就擒！','看招！'][Math.floor(Math.random()*3)],1400);if(m.hp<=0){monFlee(m);m.foe=null;}}
function plBump(m){var dx=PL.pos[0]-m.p[0],dz=PL.pos[2]-m.p[1],d=Math.hypot(dx,dz)||1;PL.pos[0]+=dx/d*1.2;PL.pos[2]+=dz/d*1.2;if(inCap(PL.pos[0],PL.pos[2])){keepOut(m.p,CAPR+1.2);}
  bubble(m,['滾出去！','打倒昏君！','衝啊！'][Math.floor(Math.random()*3)],1500,'bad');if(typeof smp==='function')smp('fail',0.5);if(typeof camShake==='function')camShake(0.25);
  toast('⚠ 暴民衝撞聖駕！快用飛刀驅散，或退回皇都、請巡捕支援。',2600);}
