// ---------- 攤位排在城門外大街兩側（v74） ----------
var MK_S0=GATE_S+5,MK_DS=1.9,MK_OFF=3.4,BS=null;
function roadS(x,z){var a=ROAD.a,u=stU();return (x-a[0])*u[0]+(z-a[1])*u[1];}
function roadOff(x,z){var a=ROAD.a,u=stU();return -(x-a[0])*u[1]+(z-a[1])*u[0];}
function stallPlace(S,s,side){var u=stU(),n=[-u[1],u[0]],f=side>0?[-n[0],-n[1]]:[n[0],n[1]];S.p=roadPt(s,side*MK_OFF);S.fw=f;S.yaw=Math.atan2(f[0],f[1]);S.cust=[S.p[0]+f[0]*1.15,S.p[1]+f[1]*1.15];S.c=S.c||lin(S.s.col);
  var mp=[S.p[0]-f[0]*0.25,S.p[1]-f[1]*0.25];if(!S.m){S.m=npcNew(S.s.who,S.s.n+'老闆',mp,'mer');S.m.h=1.7;}S.m.p=mp;S.m.yaw=S.yaw;}
function mkLayout(){var L=MKT.st.slice();BS={s:{id:'booth',n:'巡捕房',col:0x2a4a7a,who:'psx-18-police',say:'巡捕房招募巡捕，守城門、護聖駕。'},booth:1};L.push(BS);
  L.forEach(function(S,i){stallPlace(S,MK_S0+i*MK_DS,1);});MK2.st.forEach(function(S,i){stallPlace(S,MK_S0+i*MK_DS,-1);});BOOTH.p=BS.p.slice();
  MK2.perf.forEach(function(n,i){n.p=roadPt(MK_S0+14.4+i*0.6,i?-2.1:2.1);var c=roadPt(MK_S0+14.4+i*0.6,0);n.yaw=Math.atan2(c[0]-n.p[0],c[1]-n.p[1]);});}
function mktStalls(){return MKT.st.concat(MK2.st,BS?[BS]:[]).map(function(S){return {p:S.p,cust:S.cust,yaw:S.yaw};});}
function mktPt(){return roadPt(GATE_S+3+Math.random()*(MK_DS*7+4),(Math.random()-0.5)*4.4);}
function inStreet(x,z){var s=roadS(x,z);return s>-1&&s<GATE_S+MK_DS*7+12&&Math.abs(roadOff(x,z))<2.9;}
function stallDraw(u,depth,S){var f=S.fw,r=[f[1],-f[0]],x=S.p[0],z=S.p[1],y=gY(x,z),yw=S.yaw,L=function(a,b,c){return [x+r[0]*a+f[0]*c,y+b,z+r[1]*a+f[1]*c];},W=MKT.wood,cl=MKT.cloth;
  bx(u,depth,W,L(0,0.45,0.45),[1.3,0.9,0.5],yw);bx(u,depth,S.c,L(0,0.91,0.45),[1.34,0.03,0.54],yw);
  [[-0.62,0.2],[0.62,0.2],[-0.62,-0.4],[0.62,-0.4]].forEach(function(o){bx(u,depth,W,L(o[0],1.0,o[1]),[0.06,2.0,0.06],yw);});
  for(var k=0;k<5;k++)bx(u,depth,k%2?S.c:cl,L(-0.56+k*0.28,2.03,-0.1),[0.28,0.04,0.95],yw);
  bx(u,depth,[0.12,0.08,0.05],L(0,1.78,0.71),[0.8,0.26,0.03],yw);
  if(S.s.goods||S.s.pets)mk2Goods(u,depth,S,L);else if(S.booth){bx(u,depth,[0.85,0.8,0.7],L(-0.3,0.95,0.45),[0.3,0.02,0.22],yw);bx(u,depth,[0.15,0.15,0.18],L(0.3,0.99,0.45),[0.12,0.1,0.08],yw);}
  else for(var g=0;g<4;g++){var c=[S.c[0]*0.6+0.3,S.c[1]*0.6+0.25,S.c[2]*0.6+0.2];for(var h=0;h<3;h++)bx(u,depth,h%2?c:[c[0]*0.8,c[1]*0.8,c[2]*0.8],L(-0.45+g*0.3,0.95+h*0.045,0.45),[0.24,0.04,0.2],yw+0.1*h);}
  if(typeof extraOK==='function'&&extraOK()&&HUM.m2m&&S.m)npcDraw(u,depth,S.m);}
function mk2Draw(u,depth){MKT.st.concat(MK2.st,BS?[BS]:[]).forEach(function(S){if(S.p)stallDraw(u,depth,S);});
  // 大街上空的燈籠串
  for(var q=0;q<4;q++){var s=MK_S0-0.9+q*4.4,a=roadPt(s,4.35),b=roadPt(s,-4.35);[a,b].forEach(function(p){bx(u,depth,MKT.wood,[p[0],gY(p[0],p[1])+1.65,p[1]],[0.08,3.3,0.08]);});
    for(var j=0;j<7;j++){var t=(j+0.5)/7,x=a[0]+(b[0]-a[0])*t,z=a[1]+(b[1]-a[1])*t,yy=gY(x,z)+3.15-Math.sin(t*Math.PI)*0.3;bx(u,depth,j%3===1?[0.9,0.62,0.12]:[0.78,0.08,0.05],[x,yy,z],[0.12,0.16,0.12],0,MK2.sph);}}
  if(typeof extraOK==='function'&&extraOK()&&HUM.m2m)MK2.perf.forEach(function(n){npcDraw(u,depth,n);});}
function mk2Goods(u,depth,S,L){var id=S.s.id,K=typeof KCM!=='undefined',yw=S.yaw;
  if(id==='bun'){for(var i=0;i<3;i++){bx(u,depth,[0.55,0.4,0.22],L(-0.4+i*0.4,0.99,0.45),[0.3,0.12,0.3],yw,MK2.cyl);if(K)for(var j=0;j<3;j++)kcDraw(u,depth,'bun',L(-0.45+i*0.4+j*0.05,1.05,0.39+j*0.06),j,0.11);}}
  else if(id==='veg'&&K){for(i=0;i<4;i++)kcDraw(u,depth,'tomato',L(-0.5+i*0.12,0.93,0.35+(i%2)*0.1),i,0.09);kcDraw(u,depth,'crLet',L(0.25,0.93,0.45),yw,0.5);}
  else if(id==='tea'){bx(u,depth,[0.3,0.32,0.36],L(-0.35,1.03,0.45),[0.12,0.2,0.12],yw,MK2.cyl);for(i=0;i<4;i++)bx(u,depth,[0.85,0.83,0.78],L(i*0.15-0.05,0.96,0.5),[0.05,0.06,0.05],yw,MK2.cyl);}
  else if(id==='candy'){for(i=0;i<6;i++){bx(u,depth,[0.6,0.45,0.25],L(-0.4+i*0.16,1.18,0.45),[0.012,0.5,0.012],yw);for(var k=0;k<4;k++)bx(u,depth,[0.75,0.06,0.06],L(-0.4+i*0.16,1.25+k*0.06,0.45),[0.03,0.03,0.03],0,MK2.sph);}}
  else if(id==='meat'&&K){kcDraw(u,depth,'board',L(0,0.93,0.45),yw,0.6);kcDraw(u,depth,'ham',L(-0.14,0.95,0.45),yw+0.4,0.18);kcDraw(u,depth,'steak',L(0.16,0.95,0.48),yw+1,0.17);kcDraw(u,depth,'knife',L(0.05,0.955,0.35),yw+1.5,0.4);}
  else if(id==='lamp'){for(i=0;i<5;i++)bx(u,depth,i%2?[0.85,0.55,0.1]:[0.8,0.1,0.06],L(-0.5+i*0.25,1.78,-0.2),[0.09,0.12,0.09],0,MK2.sph);}
  else if(id==='pet'){bx(u,depth,[0.55,0.42,0.25],L(-0.3,1.05,0.45),[0.36,0.24,0.3],yw);bx(u,depth,[0.55,0.42,0.25],L(0.3,1.05,0.45),[0.36,0.24,0.3],yw);}}
function mk2Init(){STALL2.forEach(function(s){MK2.st.push({s:s,c:lin(s.col),f:-1});});MK2.sph=mesh(geoSphere(1,10,8));MK2.cyl=mesh(geoCyl(1,1,1,10));
  var a=npcNew('psx-05','雜耍藝人',[0,0],'perf');a.act='dance';var b=npcNew('psx-26-doctor','說書先生',[0,0],'perf');b.act='talk';MK2.perf=[a,b];mkLayout();}
// ---------- 動物（anyCreature 生成） ----------

function aniRec(id){if(typeof ANIMALS==='undefined')return null;for(var i=0;i<ANIMALS.length;i++)if(ANIMALS[i].id===id)return ANIMALS[i];return null;}
function aniActor(id,pos,h){var R=aniRec(id);if(!R)return null;var A=MK2.AG[id]||(MK2.AG[id]=loadGLB(R.glb));var a=new GActor(A,{name:R.n,pos:[pos[0],0,pos[1]],yaw:Math.random()*6.28,h:h||R.h,walk:'move',run:'move',vWalk:1.2*(h||R.h),natW:1.2*(h||R.h)});a.natW=1.3*(h||R.h);a.natR=a.natW;a.id=id;a.home=pos.slice();a.w=Math.random()*3;return a;}
function aniStep(a,dt,tx,tz,spd,stop){var dx=tx-a.pos[0],dz=tz-a.pos[2],d=Math.hypot(dx,dz);if(d<=(stop||0.3)){a.speed=0;if(a.clip!=='idle')a.play('idle',0.3);return true;}
  var v=Math.min(spd,d/Math.max(dt,1e-3));a.pos[0]+=dx/d*v*dt;a.pos[2]+=dz/d*v*dt;a.speed=v;var ty=Math.atan2(dx,dz);a.yaw+=Math.atan2(Math.sin(ty-a.yaw),Math.cos(ty-a.yaw))*Math.min(1,dt*6);if(a.clip!=='move')a.play('move',0.25);return false;}
function aniSpawn(){MK2.ani=[];if(SETS.stAni===0||typeof ANIMALS==='undefined')return;var R=function(s,o){return roadPt(MK_S0+s,o);};
  var L=[['dog',R(-2,1.6)],['dog2',R(8,-1.2)],['cat',R(3,2.6)],['cat',R(10,-2.6)],['pig',R(16,4.6)],['sheep',R(19,5)],['sheep',R(19.5,4.2)],['goat',R(17,-4.6)],['horse',roadPt(GATE_S+1.5,3.0)],['ox',R(21,-4.4)]];
  L.forEach(function(q){var a=aniActor(q[0],q[1]);if(a){a.roam=q[0]==='horse'?0.4:q[0].indexOf('dog')===0?5:2.2;a.street=1;MK2.ani.push(a);}});}
function capPt(){for(var k=0;k<20;k++){var a=Math.random()*6.283,r=6+Math.random()*7,p=[Math.cos(a)*r,Math.sin(a)*r];if(Math.abs(roadOff(p[0],p[1]))>3&&!(PADDY&&p[0]>PADDY.x0-1&&p[0]<PADDY.x1+1&&p[1]>PADDY.z0-1&&p[1]<PADDY.z1+1))return p;}return [6,-6];}
function aniUpdate(a,dt){a.w-=dt;a.y=gY(a.pos[0],a.pos[2]);
  if(a.w>0){a.speed=0;if(a.clip!=='idle')a.play('idle',0.3);}
  else{if(!a.tg)a.tg=a.pet?capPt():[a.home[0]+(Math.random()-0.5)*2*a.roam,a.home[1]+(Math.random()-0.5)*2*a.roam];if(aniStep(a,dt,a.tg[0],a.tg[1],0.6+0.15*a.h,0.3)){a.tg=null;a.w=3+Math.random()*7;}}
  if(a.pet){var r=Math.hypot(a.pos[0],a.pos[2]);if(r>CAPR-1){a.pos[0]*=(CAPR-1)/r;a.pos[2]*=(CAPR-1)/r;a.tg=null;}}
  a.update(dt);}
// ---------- 寵物：養在皇都裡自由走動，可流放 ----------
var PET_MAX=6;
function petSync(){var L=G.pets||[],key=L.join(',');if(MK2.pk===key)return;MK2.pk=key;var old=MK2.pets;MK2.pets=[];L.forEach(function(id,i){var o=old.filter(function(a){return a.id===id&&MK2.pets.indexOf(a)<0;})[0];if(o){MK2.pets.push(o);return;}var a=aniActor(id,capPt());if(a){a.pet=1;a.h=Math.min(a.h,id==='horse'?1.5:id==='ox'?1.2:a.h);MK2.pets.push(a);}});}
function petOpen(S){var own=G.pets||[],h='<h2>🐾 '+(S?S.s.n:'宮中動物')+'</h2><p class="court">買回去的動物會養在皇都裡自由走動（最多 '+PET_MAX+' 隻，目前 '+own.length+' 隻）。不想養了可以「流放」到山野。</p><div class="shTop"><span>🪙 '+gold()+'</span></div>'+
  (own.length?'<h3>宮中的動物</h3><div class="shList">'+own.map(function(id,i){var R=aniRec(id);return '<div class="shIt">'+thumbH('pet:'+id)+'<b>'+(R?R.n:id)+'</b><button class="b2" data-exile="'+i+'">🌄 流放</button></div>';}).join('')+'</div>':'')+
  (S?'<h3>販售</h3><div class="shList">'+(typeof ANIMALS==='undefined'?'<p>貨還沒到，稍等一下再來。</p>':ANIMALS.map(function(R){return '<div class="shIt">'+thumbH('pet:'+R.id)+'<b>'+R.n+'</b><small>養在皇都裡</small><button class="b1" data-pet="'+R.id+'">🪙 '+PET_P[R.id]+'</button></div>';}).join(''))+'</div>':'');
  openCard(h,'notes');[].forEach.call(document.querySelectorAll('#cardBody [data-pet]'),function(b){b.onclick=function(){var id=b.dataset.pet,p=PET_P[id];G.pets=G.pets||[];if(G.pets.length>=PET_MAX){toast('最多養 '+PET_MAX+' 隻。',2000);return;}if(gold()<p){toast('金幣不夠。',2000);smp('fail',0.5);return;}
    G.gold=gold()-p;G.pets.push(id);saveG();goldChip();smp('success',0.6);toast('🐾 '+aniRec(id).n+'已送進皇都。',2200);petSync();petOpen(S);};});
  [].forEach.call(document.querySelectorAll('#cardBody [data-exile]'),function(b){b.onclick=function(){var i=+b.dataset.exile,id=G.pets[i],R=aniRec(id);G.pets.splice(i,1);saveG();petSync();smp('drop',0.4);toast('🌄 '+(R?R.n:'')+'已流放到山野。',2200);petOpen(S);};});}
function petNear(){var best=null,bd=1.8;MK2.pets.forEach(function(a){var d=Math.hypot(a.pos[0]-PL.pos[0],a.pos[2]-PL.pos[2]);if(d<bd){bd=d;best=a;}});return best;}
// ---------- 商品縮圖與試穿 ----------
var ACC_IC={ear:'👂',tail:'🦊',horn:'🦌',wing:'🪽',top:'✨',face:'🕶️'};
function thumbH(id,it){var t=typeof THUMB!=='undefined'&&THUMB[id];if(t)return '<img class="thI" src="'+t+'" alt="">';var e=it&&it.slot==='acc'?(ACC_IC[it.ak]||'🎁'):'🎁';return '<span class="thI thE">'+e+'</span>';}
var TRY=null;
function tryOn(it,S,tab){if(TRY)tryEnd(false);var prev=null;try{prev=localStorage.getItem('tang_char_pl');}catch(e){}TRY={it:it,prev:prev,S:S,tab:tab,cam:{f:CFG.follow,th:cam.theta,r:cam.r,ph:cam.phi}};equip(it,true);closeCard();
  CFG.follow=0;cam.theta=PL.yaw;cam.r=it.slot==='hat'||it.slot==='mask'||it.slot==='hair'||it.slot==='skin'?1.7:3.0;cam.phi=1.42;cam.hold=999;
  var b=document.createElement('div');b.id='tryBar';b.innerHTML='<b>👁 試穿：'+esc(it.n)+'</b><button class="b1" id="tryBuy">🪙 '+it.p+' 買下</button><button class="b2" id="tryNo">脫下</button><button class="b2" id="tryRot">↻</button>';document.body.appendChild(b);
  $('tryNo').onclick=function(){tryEnd(false);};$('tryRot').onclick=function(){cam.theta+=Math.PI/2;};$('tryBuy').onclick=function(){if(gold()<it.p){toast('金幣不夠。',2000);smp('fail',0.5);return;}G.gold=gold()-it.p;G.own=G.own||{};G.own[it.id]=1;saveG();goldChip();smp('success',0.6);toast('買下了「'+it.n+'」，已經穿在身上。',2400);tryEnd(true);};}
function tryEnd(keep){if(!TRY)return;var T=TRY;TRY=null;if(!keep){try{if(T.prev==null)localStorage.removeItem('tang_char_pl');else localStorage.setItem('tang_char_pl',T.prev);}catch(e){}humApply('pl');}
  CFG.follow=T.cam.f;cam.theta=T.cam.th;cam.r=T.cam.r;cam.phi=T.cam.ph;cam.hold=0;var b=$('tryBar');if(b)b.remove();if(T.S)shopOpen(T.S,T.tab);}
// ---------- 不穿模：居民、巡捕、怪客、動物彼此分開，也不穿過攤位與皇上 ----------
function pushO(p,r,o){if(o.t==='c'){var dx=p[0]-o.x,dz=p[1]-o.z,d=Math.hypot(dx,dz),m=o.r+r;if(d<m&&d>1e-4){p[0]=o.x+dx/d*m;p[1]=o.z+dz/d*m;}}
  else{var cx=Math.max(o.x-o.w,Math.min(o.x+o.w,p[0])),cz=Math.max(o.z-o.d,Math.min(o.z+o.d,p[1])),ex=p[0]-cx,ez=p[1]-cz,e=Math.hypot(ex,ez);if(e<r&&e>1e-4){p[0]=cx+ex/e*r;p[1]=cz+ez/e*r;}}}
function sepAll(){var E=[],add=function(o,r,isA){if(!o||o.hide)return;var p=isA?[o.pos[0],o.pos[2]]:[o.p[0],o.p[1]];E.push({o:o,p:p,r:r,a:isA,x0:p[0],z0:p[1]});};
  ST.npc.forEach(function(n){add(n,0.28);});ST.cop.forEach(function(n){add(n,0.3);});ST.mon.forEach(function(n){add(n,0.3*(n.k2||1));});MK2.serv.forEach(function(n){add(n,0.28);});
  MK2.ani.concat(MK2.pets).forEach(function(a){add(a,0.12+0.2*a.h,1);});
  var ob=typeof OBST!=='undefined'&&OBST?OBST:[],stat=MK2.perf.map(function(n){return {p:n.p,r:0.3};}).concat(MKT.st.concat(MK2.st).map(function(S){return {p:S.m?S.m.p:[0,0],r:0.3};}));
  for(var i=0;i<E.length;i++){var A=E[i];for(var j=i+1;j<E.length;j++){var B=E[j],dx=B.p[0]-A.p[0],dz=B.p[1]-A.p[1],d=Math.hypot(dx,dz),m=A.r+B.r;if(d<m&&d>1e-4){var k=(m-d)/d*0.5;A.p[0]-=dx*k;A.p[1]-=dz*k;B.p[0]+=dx*k;B.p[1]+=dz*k;}}
    stat.forEach(function(s){var dx=A.p[0]-s.p[0],dz=A.p[1]-s.p[1],d=Math.hypot(dx,dz),m=A.r+s.r;if(d<m&&d>1e-4){A.p[0]=s.p[0]+dx/d*m;A.p[1]=s.p[1]+dz/d*m;}});
    var px=A.p[0]-PL.pos[0],pz=A.p[1]-PL.pos[2],pd=Math.hypot(px,pz),pm=A.r+0.34;if(pd<pm&&pd>1e-4){var kk=(pm-pd)/pd;A.p[0]+=px*kk*0.4;A.p[1]+=pz*kk*0.4;PL.pos[0]-=px*kk*0.6;PL.pos[2]-=pz*kk*0.6;}
    for(var q=0;q<ob.length;q++)pushO(A.p,A.r,ob[q]);}
  E.forEach(function(A){if(A.a){A.o.pos[0]=A.p[0];A.o.pos[2]=A.p[1];}else{A.o.p[0]=A.p[0];A.o.p[1]=A.p[1];}});}

// ---------- 小吃、茶水、燈籠 ----------
function goodsOpen(S){var h='<h2>🏮 '+S.s.n+'</h2><p class="court">'+S.s.shout[0]+'</p><div class="shTop"><span>🪙 '+gold()+'</span>'+(S.s.id==='lamp'?'<span>宮中已掛 '+(G.lamps||0)+' 盞</span>':'')+'</div><div class="shList">'+
  S.s.goods.map(function(g,i){return '<div class="shIt">'+thumbH('g:'+S.s.id+':'+i)+'<b>'+g[0]+'</b><small>'+(g[2]==='lamp'?'掛在宮苑裡':g[2]==='drink'?'現泡現喝':'現做現吃')+'</small><button class="b1" data-g="'+i+'">🪙 '+g[1]+'</button></div>';}).join('')+'</div>';
  openCard(h,'notes');[].forEach.call(document.querySelectorAll('#cardBody [data-g]'),function(b){b.onclick=function(){var g=S.s.goods[+b.dataset.g];if(gold()<g[1]){toast('金幣不夠。',2000);smp('fail',0.5);return;}G.gold=gold()-g[1];saveG();goldChip();smp('success',0.5);
    if(g[2]==='lamp'){G.lamps=Math.min(16,(G.lamps||0)+1);saveG();toast('🏮 「'+g[0]+'」已掛到宮苑裡。',2200);goodsOpen(S);return;}
    closeCard();var c=PL.A&&(PL.A.anims.m_eatC?'m_eatC':PL.A.anims.eat?'eat':null);if(c){PL.once=c;PL.play(c,0.2);PL.t=0;}toast((g[2]==='drink'?'🍵 皇上喝了一口「':'😋 皇上嚐了一口「')+g[0]+'」，讚不絕口。',2400);bubble(S.m,['多謝皇上賞光！','皇上吃得開心，小的三生有幸！'][Math.floor(Math.random()*2)],2000,'good');};});}
function lampDraw(u,depth){var n=G.lamps||0;for(var i=0;i<n;i++){var a=i/16*6.283+0.35,r=8.9,x=Math.cos(a)*r,z=Math.sin(a)*r,y=gY(x,z);bx(u,depth,MKT.wood,[x,y+1.25,z],[0.06,2.5,0.06]);bx(u,depth,MKT.wood,[x,y+2.45,z+0.18],[0.04,0.04,0.4]);
  bx(u,depth,i%3===1?[0.9,0.6,0.1]:[0.82,0.1,0.06],[x,y+2.2,z+0.36],[0.17,0.22,0.17],0,MK2.sph);}}
