function npcNat(){if(V79.natM)return V79.natM;var MA=HUM.m2m;if(!MA)return {walk:1.25,jog:2.2,run:4.5};var ni=MA.nodes.findIndex(function(x){return x.name==='foot_l';}),hd=MA.nodes.findIndex(function(x){return x.name==='head';});
  var W=gpose(MA,null,0,null,0,M4.ident()).world,Hm=(W[hd][13]-W[ni][13])*1.08||1,k=1.72/Hm,N=natOf(MA,['walk','jog','run'],ni),o={};['walk','jog','run'].forEach(function(c){o[c]=(N[c]||[1.25,2.2,4.5][['walk','jog','run'].indexOf(c)]/k)*k;});V79.natM=o;return o;}
