    $('frR').oninput=function(){VIEWS.far.r=+this.value;$('frV').textContent=VIEWS.far.r.toFixed(1);apply();};$('frP').oninput=function(){VIEWS.far.phi=+this.value;$('fpV').textContent=Math.round(90-VIEWS.far.phi*57.3);apply();};
