// ---------- 御膳房：自由烹調 → 系統評分 → 端上桌享用 ----------
var CKX={target:null,st:null,dish:null,d:null};
function ckGrade(plate,r){if(!plate.length)return null;var used=plate.map(function(){return false;}),pts=0,note=[];
  r[1].forEach(function(x){var i=plate.findIndex(function(it,j){return !used[j]&&it.k===x[0]&&it.st===x[1];});if(i>=0){used[i]=true;pts+=10;return;}
    i=plate.findIndex(function(it,j){return !used[j]&&it.k===x[0];});var nm=CK_ING[x[0]][0];if(i<0){note.push('少了'+nm);return;}used[i]=true;var s=plate[i].st;
    if(s===3){pts+=2;note.push(nm+'燒焦了');}else if(s<x[1]){pts+=5;note.push(nm+(x[1]===2?'還沒熟':'沒切'));}else{pts+=6;note.push(nm+'煮過頭了');}});
  var extra=used.filter(function(u){return !u;}).length;if(extra)note.push('多放了 '+extra+' 樣不搭的食材');
  return {s:Math.max(0,Math.min(100,Math.round(pts/(r[1].length*10)*100)-extra*6)),note:note};}
