    var o=b.querySelector('.ckOrd .ckT b');if(o&&!/建議菜色/.test(o.textContent))o.textContent='🍳 建議菜色：'+CK.orders[0].r[0];var ord=b.querySelector('.ckOrd');if(ord&&!ord.querySelector('#ckNext')){var x=document.createElement('button');x.id='ckNext';x.textContent='換一道';x.style.cssText='background:#5a3a22;color:#fff;border:1px solid #a87a3a;border-radius:10px;padding:2px 10px';x.onclick=function(){var r;do{r=pick(CK_REC);}while(r===CKX.target&&CK_REC.length>1);CKX.target=r;CK.orders=[{r:r,t:1e9,max:1e9}];ckRender();};ord.appendChild(x);}
    if(light)return;var a=$('ckAdd');if(a)a.onclick=function(){if(!CK.hand)return;if(CK.plate.length>=8){toast('盤子已經堆滿了',1200);return;}CK.plate.push(CK.hand);CK.hand=null;smp('drop',0.45);ckRender();};
