// ==========================================================================
// 萬用人型模組（HMOD）＋人型模組工作室
//  ・同一副人體（MakeHuman 素體＋22 根骨頭）＋同一套動作，皇上、太監、太子都套用；之後 NPC 也改用這副。
//  ・可調：體型（性別、年紀、肌肉、胖瘦、身高）、臉型、比例（軀幹、脖子、頭、肩寬、上臂、前臂、手、骨盆、大腿、小腿、腳）、
//    關節位置（只動骨頭樞紐、不動外皮）、姿勢修正（每根骨頭在所有動作上額外轉一個角度）、服裝髮型配件。
//  ・調好後「模組碼」一鍵複製，貼回來就能定案成預設值。
// ==========================================================================
var HMOD={DEF:{}};   /* 定案後的預設值放這裡：{pl:{prop,jo,corr},eu:{…},pr:{…}} */
var HM_PROP=[['torso','軀幹長度',0.8,1.25],['neck','脖子長度',0.5,1.7],['head','頭的大小',0.8,1.25],['shW','肩膀寬度',0.6,1.5],['arm','上臂長度',0.8,1.25],['fore','前臂長度',0.8,1.25],
  ['hand','手掌大小',0.75,1.35],['hipW','骨盆寬度',0.75,1.35],['leg','大腿長度',0.8,1.25],['shin','小腿長度',0.8,1.25],['foot','腳掌大小',0.75,1.35]];
var HM_CH={hips:'spine1',spine1:'spine2',spine2:'neck',neck:'head',clL:'upL',upL:'foL',foL:'haL',clR:'upR',upR:'foR',foR:'haR',thL:'knL',knL:'ftL',ftL:'toL',thR:'knR',knR:'ftR',ftR:'toR'};
var HM_SEG={hips:'torso',spine1:'torso',spine2:'torso',neck:'neck',clL:'shW',clR:'shW',upL:'arm',upR:'arm',foL:'fore',foR:'fore',thL:'leg',thR:'leg',knL:'shin',knR:'shin',ftL:'foot',ftR:'foot'};
